window.PACK_DATA = window.PACK_DATA || {};
window.PACK_DATA["n3/grammar"] = [
  {id:"g-n3-wake-da",type:"grammar",source:"JLPT N3",level:"N3",title:"〜わけだ – kein Wunder, deshalb also",jp:"〜わけだ",summary:"Zieht den naheliegenden Schluss aus einer Tatsache, die man gerade erfahren oder genannt hat: „deshalb also“, „kein Wunder, dass …“. Es kann auch zusammenfassen, worauf etwas hinausläuft („das heißt also …“). はずだ ist eine Erwartung, die noch nicht bestätigt ist; わけだ erklärt etwas, das schon feststeht.",structure:["Kurzform + わけだ","な-Adjektiv + な + わけだ","Nomen + な／という + わけだ"],examples:[{jp:"窓[まど]が開[あ]いていますね。寒[さむ]いわけです。",de:"Das Fenster ist ja offen. Kein Wunder, dass es kalt ist.",en:"The window is open. No wonder it is cold."},{jp:"田中[たなか]さんは十年[じゅうねん]もパリに住[す]んでいたそうです。フランス語[ご]が上手[じょうず]なわけだ。",de:"Herr Tanaka soll zehn Jahre in Paris gelebt haben. Kein Wunder, dass sein Französisch gut ist.",en:"I hear Mr Tanaka lived in Paris for ten years. No wonder his French is good."}],matches:[],tags:["erklärung","schlussfolgerung"]},
  {id:"g-n3-wake-ga-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜わけがない – das kann unmöglich sein",jp:"〜わけがない",summary:"Eine starke, subjektive Verneinung: Es gibt keinen Grund, warum etwas stimmen könnte, also ist es ausgeschlossen. Sehr nah an はずがない, aber emotionaler. In der Umgangssprache fällt が oft weg: わけない.",structure:["Kurzform + わけがない","な-Adjektiv + な + わけがない","Nomen + の／な + わけがない"],examples:[{jp:"こんなに難[むずか]しい問題[もんだい]が、子[こ]どもにできるわけがない。",de:"Eine so schwierige Aufgabe kann ein Kind unmöglich lösen.",en:"There is no way a child can solve such a difficult problem."},{jp:"あんなに練習[れんしゅう]したんだから、負[ま]けるわけがないよ。",de:"Wir haben so viel geübt, wir können gar nicht verlieren.",en:"We practised so much, there is no way we will lose."}],matches:[],tags:["vermutung","verneinung"]},
  {id:"g-n3-wake-dewa-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜わけではない – das heißt nicht, dass; nicht unbedingt",jp:"〜わけではない",summary:"Eine teilweise, sanfte Verneinung: Sie korrigiert einen Schluss, den der Zuhörer ziehen könnte („es ist nicht so, dass …“, „nicht unbedingt“). Steht oft mit いつも, ぜんぶ, みんな oder からといって. Umgangssprachlich: わけじゃない.",structure:["Kurzform + わけではない","な-Adjektiv + な + わけではない","Nomen + な／という + わけではない"],examples:[{jp:"肉[にく]が嫌[きら]いなわけではありませんが、あまり食[た]べません。",de:"Es ist nicht so, dass ich Fleisch nicht mag, aber ich esse nicht viel davon.",en:"It is not that I dislike meat, but I do not eat it much."},{jp:"高[たか]い物[もの]がいつもいいわけではない。",de:"Teure Sachen sind nicht immer gut.",en:"Expensive things are not always good."}],matches:[],tags:["verneinung","erklärung"]},
  {id:"g-n3-wake-niwa-ikanai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜わけにはいかない – kann (schlecht) tun, es geht nicht an",jp:"〜わけにはいかない",summary:"Sagt, dass man etwas nicht tun kann, weil die Pflicht, das Gewissen oder die Erwartungen der anderen dagegen sprechen – nicht, weil man dazu nicht fähig wäre (das wäre できない). Mit der ない-Form bedeutet es das Gegenteil: Man kommt nicht darum herum, es zu tun.",structure:["Wörterbuchform + わけにはいかない","ない-Form + わけにはいかない (= müssen)"],examples:[{jp:"明日[あした]は大事[だいじ]な試験[しけん]があるから、休[やす]むわけにはいかない。",de:"Morgen habe ich eine wichtige Prüfung, da kann ich nicht einfach fehlen.",en:"I have an important exam tomorrow, so I cannot stay at home."},{jp:"約束[やくそく]したので、行[い]かないわけにはいきません。",de:"Ich habe es versprochen, also muss ich hingehen.",en:"I promised, so I have to go."}],matches:[],tags:["pflicht","unmöglichkeit"]},
  {id:"g-n3-beki",type:"grammar",source:"JLPT N3",level:"N3",title:"〜べきだ – sollte, es gehört sich",jp:"〜べきだ",summary:"Sagt, was der Sprecher für das Richtige hält. Es ist eine starke Meinung, keine Regel und kein Gesetz (dafür nimmt man なければならない), und klingt gegenüber Höhergestellten hart; ほうがいい ist sanfter. べきだった bedeutet „hätte tun sollen“. Aus する kann すべき werden.",structure:["Wörterbuchform + べきだ","する → するべきだ／すべきだ","Wörterbuchform + べき + Nomen"],examples:[{jp:"借[か]りたお金[かね]はすぐに返[かえ]すべきだ。",de:"Geliehenes Geld sollte man sofort zurückgeben.",en:"You should give back borrowed money right away."},{jp:"学生[がくせい]のうちに、もっと本[ほん]を読[よ]んでおくべきでした。",de:"Ich hätte als Student mehr Bücher lesen sollen.",en:"I should have read more books while I was a student."}],matches:[],tags:["pflicht","rat"]},
  {id:"g-n3-beki-dewa-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜べきではない – sollte nicht",jp:"〜べきではない",summary:"Die Verneinung von べきだ: Der Sprecher hält es für falsch, etwas zu tun. Achtung: Das Verb bleibt in der Wörterbuchform, verneint wird べき – also nicht ない-Form + べき. べきではなかった bedeutet „hätte nicht tun sollen“.",structure:["Wörterbuchform + べきではない","Wörterbuchform + べきではなかった"],examples:[{jp:"人[ひと]の悪口[わるくち]を言[い]うべきではありません。",de:"Man sollte nicht schlecht über andere reden.",en:"You should not speak badly of other people."},{jp:"あんなことを言[い]うべきではなかった。",de:"So etwas hätte ich nicht sagen sollen.",en:"I should not have said such a thing."}],matches:[],tags:["pflicht","rat"]},
  {id:"g-n3-koto-da",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ことだ – man sollte (Ratschlag)",jp:"〜ことだ",summary:"Gibt einen Rat, was in einer bestimmten Lage das Beste ist: „es kommt darauf an, … zu tun“. So spricht jemand, der es besser weiß (Lehrer, Arzt, ältere Person); gegenüber Höhergestellten verwendet man es deshalb nicht.",structure:["Wörterbuchform + ことだ","ない-Form + ことだ"],examples:[{jp:"日本語[にほんご]が上手[じょうず]になりたければ、毎日[まいにち]話[はな]すことだ。",de:"Wenn du gut Japanisch können willst, solltest du es jeden Tag sprechen.",en:"If you want to get good at Japanese, you should speak it every day."},{jp:"風邪[かぜ]のときは、無理[むり]をしないことです。",de:"Bei einer Erkältung sollte man sich nicht überanstrengen.",en:"When you have a cold, you should not push yourself."}],matches:[],tags:["rat"]},
  {id:"g-n3-koto-instruction",type:"grammar",source:"JLPT N3",level:"N3",title:"〜こと – man muss (schriftliche Anweisung)",jp:"〜こと",summary:"Ganz am Satzende macht こと aus dem Satz eine Anweisung oder Regel. Man findet es auf Aushängen, in Schulordnungen oder auf Aufgabenblättern; im Gespräch wird es nicht verwendet. Anders als das こと, das ein Verb zum Nomen macht („das …-en“), folgt hier nichts mehr.",structure:["Wörterbuchform + こと。","ない-Form + こと。"],examples:[{jp:"レポートは金曜日[きんようび]までに出[だ]すこと。",de:"Die Berichte sind bis Freitag abzugeben.",en:"Reports must be handed in by Friday."},{jp:"教室[きょうしつ]で物[もの]を食[た]べないこと。",de:"Im Klassenzimmer nicht essen.",en:"Do not eat in the classroom."}],matches:[],tags:["befehl","schriftsprache"]},
  {id:"g-n3-koto-wa-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ことはない – es ist nicht nötig, zu",jp:"〜ことはない",summary:"Sagt jemandem, dass eine Handlung unnötig ist, meist um zu beruhigen oder Mut zu machen: „du brauchst nicht zu …“. Es ist ein Rat an den Zuhörer; für die eigene Lage nimmt man なくてもいい.",structure:["Wörterbuchform + ことはない"],examples:[{jp:"時間[じかん]はまだあるから、急[いそ]ぐことはありません。",de:"Wir haben noch Zeit, es gibt keinen Grund zur Eile.",en:"There is still time, so there is no need to hurry."},{jp:"君[きみ]が悪[わる]いんじゃないから、謝[あやま]ることはないよ。",de:"Du bist nicht schuld, du brauchst dich also nicht zu entschuldigen.",en:"It is not your fault, so you do not need to apologise."}],matches:[],tags:["rat","notwendigkeit"]},
  {id:"g-n3-koto-ka",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ことか – wie sehr …! was für ein …!",jp:"〜ことか",summary:"Ein Ausruf starken Gefühls: Das Ausmaß ist so groß, dass man es kaum in Worte fassen kann. Steht zusammen mit どんなに, どれほど, なんと oder なんど; klingt eher literarisch.",structure:["どんなに／なんど + Kurzform + ことか","な-Adjektiv + な + ことか"],examples:[{jp:"合格[ごうかく]の知[し]らせを聞[き]いて、どんなにうれしかったことか。",de:"Wie sehr habe ich mich gefreut, als ich hörte, dass ich bestanden habe!",en:"How happy I was when I heard that I had passed!"},{jp:"何度[なんど]注意[ちゅうい]したことか。",de:"Wie oft habe ich ihn schon ermahnt!",en:"How many times have I warned him!"}],matches:[],tags:["ausruf","gefühl"]},
  {id:"g-n3-koto-ga-aru",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ことがある – es kommt vor, dass; manchmal",jp:"〜ことがある",summary:"Mit einem Verb in der Gegenwart sagt ことがある, dass etwas ab und zu geschieht. Nicht verwechseln mit た-Form + ことがある („schon einmal getan haben“), das von Erfahrung spricht. Steht oft mit ときどき oder たまに; こともある bedeutet „es kommt auch vor, dass“.",structure:["Wörterbuchform + ことがある","ない-Form + ことがある"],examples:[{jp:"朝[あさ]ご飯[はん]を食[た]べないで会社[かいしゃ]に行[い]くことがあります。",de:"Es kommt vor, dass ich ohne Frühstück zur Arbeit gehe.",en:"There are times when I go to work without eating breakfast."},{jp:"父[ちち]はたまに晩[ばん]ご飯[はん]を作[つく]ることがある。",de:"Mein Vater kocht gelegentlich das Abendessen.",en:"My father occasionally cooks dinner."}],matches:[],tags:["häufigkeit"]},
  {id:"g-n3-koto-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ことに – zu meiner (Überraschung, Freude …)",jp:"〜ことに",summary:"Ein Gefühlswort + ことに am Satzanfang nimmt vorweg, wie der Sprecher das Folgende empfindet: „zu meiner Überraschung“, „zum Glück“, „leider“. Vor allem Schriftsprache. (Das Adverb ことに für sich allein ist ein förmliches Wort für „besonders“, wie とくに.)",structure:["い-Adjektiv + ことに","な-Adjektiv + な + ことに","た-Form + ことに (おどろいたことに)"],examples:[{jp:"うれしいことに、友[とも]だちが駅[えき]まで迎[むか]えに来[き]てくれた。",de:"Zu meiner Freude hat mich meine Freundin am Bahnhof abgeholt.",en:"To my delight, my friend came to the station to pick me up."},{jp:"驚[おどろ]いたことに、その店[みせ]はもうなくなっていた。",de:"Zu meiner Überraschung gab es den Laden schon nicht mehr.",en:"To my surprise, the shop was already gone."}],matches:[],tags:["gefühl","schriftsprache"]},
  {id:"g-n3-koto-kara",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ことから – aus der Tatsache, dass; weil",jp:"〜ことから",summary:"Nennt die Tatsache, auf der eine Schlussfolgerung beruht oder von der ein Name herkommt: „daraus, dass …, schließt man …“, „weil …, heißt es …“. Vor allem Schriftsprache.",structure:["Kurzform + ことから","な-Adjektiv + な／である + ことから","Nomen + である + ことから"],examples:[{jp:"この町[まち]は、桜[さくら]の木[き]が多[おお]いことから「桜町[さくらまち]」と呼[よ]ばれている。",de:"Diese Stadt wird „Sakuramachi“ genannt, weil es dort viele Kirschbäume gibt.",en:"This town is called \"Sakuramachi\" because it has many cherry trees."},{jp:"道[みち]がぬれていることから、夜[よる]に雨[あめ]が降[ふ]ったことが分[わ]かる。",de:"Daran, dass die Straße nass ist, erkennt man, dass es in der Nacht geregnet hat.",en:"From the fact that the road is wet you can tell that it rained during the night."}],matches:[],tags:["grund","schriftsprache"]},
  {id:"g-n3-mono-da",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ものだ – so ist das eben; es gehört sich",jp:"〜ものだ",summary:"Sagt, was natürlich oder allgemein wahr ist („so ist das nun einmal“), und davon ausgehend, was man normalerweise zu tun hat. べきだ ist die persönliche Meinung des Sprechers; ものだ beruft sich auf das, was allgemein gilt. Die Verneinung ist ものではない („das tut man nicht“), die umgangssprachliche Form もんだ.",structure:["Wörterbuchform／ない-Form + ものだ","い-Adjektiv + ものだ","な-Adjektiv + な + ものだ"],examples:[{jp:"人[ひと]の気持[きも]ちは変[か]わるものだ。",de:"Die Gefühle der Menschen ändern sich eben.",en:"People's feelings change – that is how it is."},{jp:"お年寄[としよ]りには席[せき]を譲[ゆず]るものだ。",de:"Älteren Leuten bietet man seinen Platz an.",en:"One should offer one's seat to elderly people."}],matches:[],tags:["allgemeingültig","pflicht"]},
  {id:"g-n3-ta-mono-da",type:"grammar",source:"JLPT N3",level:"N3",title:"〜たものだ – früher oft (wehmütige Erinnerung)",jp:"〜たものだ",summary:"た-Form + ものだ blickt mit Gefühl auf etwas zurück, das man früher oft getan hat: „damals habe ich immer …“. Steht typischerweise mit よく sowie einer Zeitangabe wie こどものころ oder むかし.",structure:["た-Form + ものだ"],examples:[{jp:"子[こ]どものころ、よくこの川[かわ]で泳[およ]いだものだ。",de:"Als Kind bin ich oft in diesem Fluss geschwommen.",en:"When I was a child, I often used to swim in this river."},{jp:"学生時代[がくせいじだい]は、朝[あさ]まで友[とも]だちと話[はな]したものです。",de:"In meiner Studienzeit habe ich oft bis zum Morgen mit Freunden geredet.",en:"In my student days I would talk with my friends until morning."}],matches:[],tags:["vergangenheit","erinnerung"]},
  {id:"g-n3-mono-reason",type:"grammar",source:"JLPT N3",level:"N3",title:"〜もの／〜もん – weil ja, nun mal",jp:"〜もの／〜もん",summary:"Am Satzende nennt もの (umgangssprachlich もん) einen persönlichen Grund, oft als Ausrede oder leicht trotzige Rechtfertigung. Sehr locker, typisch für Kinder oder vertraute Beziehungen; steht oft nach だって oder 〜んだ. Das ist nicht das Nomen もの „Ding“.",structure:["Kurzform + もの／もん","Kurzform + んだもの／んだもん"],examples:[{jp:"食[た]べたくないよ。だって、おいしくないんだもん。",de:"Ich will das nicht essen. Es schmeckt halt nicht!",en:"I do not want to eat it. Because it does not taste good!"},{jp:"一人[ひとり]で行[い]けるよ。もう子[こ]どもじゃないもの。",de:"Ich kann allein hingehen. Ich bin ja kein Kind mehr.",en:"I can go on my own. I am not a child any more, you know."}],matches:[],tags:["grund","umgangssprache"]},
  {id:"g-n3-to-iu-koto-da",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ということだ – es heißt, dass; das bedeutet",jp:"〜ということだ",summary:"Zwei Verwendungen. (1) Es gibt weiter, was man gehört oder gelesen hat, wie そうだ, aber förmlicher; häufig in Nachrichten oder Berichten. (2) Es sagt, was aus einer Tatsache folgt: „das heißt also …“, oft nach つまり. Umgangssprachlich: ってことだ.",structure:["Kurzform + ということだ","Umgangssprachlich: 〜ってことだ"],examples:[{jp:"ニュースによると、来月[らいげつ]から電気代[でんきだい]が上[あ]がるということだ。",de:"Laut den Nachrichten sollen die Strompreise ab nächstem Monat steigen.",en:"According to the news, electricity prices will go up from next month."},{jp:"返事[へんじ]がない。つまり、来[こ]ないということだ。",de:"Es kommt keine Antwort. Das heißt also, er kommt nicht.",en:"There is no reply. In other words, he is not coming."}],matches:[],tags:["hörensagen","erklärung"]},
  {id:"g-n3-to-iu-no-wa",type:"grammar",source:"JLPT N3",level:"N3",title:"〜というのは – … bedeutet; das liegt daran, dass",jp:"〜というのは",summary:"Nach einem Wort oder Ausdruck leitet というのは dessen Definition oder Erklärung ein; der Satz endet meist auf のことだ oder といういみだ. Am Satzanfang liefert es den Grund für das eben Gesagte nach; der Satz endet dann auf からだ. Umgangssprachlich: って oder っていうのは.",structure:["Nomen + というのは + … のことだ／といういみだ","Satz。というのは + … からだ"],examples:[{jp:"「禁煙[きんえん]」というのは、たばこを吸[す]ってはいけないという意味[いみ]です。",de:"„Kin'en“ bedeutet, dass man nicht rauchen darf.",en:"\"Kin'en\" means that you must not smoke."},{jp:"今日[きょう]は早[はや]く帰[かえ]ります。というのは、母[はは]が来[く]るからです。",de:"Ich gehe heute früh nach Hause. Meine Mutter kommt nämlich.",en:"I am going home early today. That is because my mother is coming."}],matches:[],tags:["definition","erklärung"]},
  {id:"g-n3-to-iu-yori",type:"grammar",source:"JLPT N3",level:"N3",title:"〜というより – eher … als, weniger … als vielmehr",jp:"〜というより",summary:"Korrigiert eine Beschreibung: A ist nicht falsch, aber B trifft es besser („nicht so sehr A als vielmehr B“). Oft folgt むしろ. Man kann も anhängen: というよりも.",structure:["Kurzform + というより","Nomen／な-Adjektiv + というより"],examples:[{jp:"今日[きょう]は涼[すず]しいというより、寒[さむ]いくらいだ。",de:"Heute ist es weniger kühl als vielmehr schon fast kalt.",en:"Today it is not so much cool as almost cold."},{jp:"彼[かれ]は先生[せんせい]というより、友[とも]だちのような人[ひと]だ。",de:"Er ist eher wie ein Freund als ein Lehrer.",en:"He is more like a friend than a teacher."}],matches:[],tags:["vergleich","korrektur"]},
  {id:"g-n3-to-itte-mo",type:"grammar",source:"JLPT N3",level:"N3",title:"〜といっても – ich sage zwar …, aber",jp:"〜といっても",summary:"Nimmt einen Teil des eben Gesagten zurück: Die Aussage stimmt, aber in Wirklichkeit ist es weniger, als der Zuhörer sich vorstellen könnte. Die zweite Satzhälfte sagt, wie klein oder begrenzt es tatsächlich ist.",structure:["Kurzform + といっても","Nomen／な-Adjektiv + (だ) + といっても"],examples:[{jp:"料理[りょうり]ができるといっても、卵焼[たまごや]きぐらいです。",de:"Ich sage zwar, dass ich kochen kann, aber es reicht gerade für ein Omelett.",en:"I say I can cook, but it is only things like omelettes."},{jp:"庭[にわ]があるといっても、とても小[ちい]さいです。",de:"Wir haben zwar einen Garten, aber er ist sehr klein.",en:"We do have a garden, but it is very small."}],matches:[],tags:["einschränkung","gegensatz"]},
  {id:"g-n3-to-iu-to",type:"grammar",source:"JLPT N3",level:"N3",title:"〜というと／〜といえば – apropos, wenn man … sagt",jp:"〜というと／〜といえば",summary:"Beide greifen ein Wort auf, um daran anzuknüpfen. Entweder nennt man, was einem dazu als Erstes einfällt („wenn man Japan sagt, denkt man an …“), oder man nimmt ein Wort, das gerade gefallen ist, um zu einem verwandten Thema überzuleiten („apropos …“). Mit というと fragt man auch nach, was der andere gemeint hat: „Mit X meinst du …?“. Umgangssprachlich: っていうと, っていえば.",structure:["Nomen + というと","Nomen + といえば"],examples:[{jp:"日本[にほん]の花[はな]というと、やはり桜[さくら]ですね。",de:"Wenn man von japanischen Blumen spricht, denkt man eben doch an die Kirschblüte.",en:"When you say Japanese flowers, it has to be cherry blossoms."},{jp:"旅行[りょこう]といえば、来月[らいげつ]北海道[ほっかいどう]に行[い]くんです。",de:"Apropos Reisen: Nächsten Monat fahre ich nach Hokkaidō.",en:"Speaking of travel, I am going to Hokkaido next month."}],matches:[],tags:["thema"]},
  {id:"g-n3-to-wa-kagiranai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜とは限らない – nicht unbedingt, nicht immer",jp:"〜とはかぎらない",summary:"Sagt, dass etwas, das man allgemein annimmt, nicht in jedem Fall stimmt: Es gibt Ausnahmen. Steht oft mit かならずしも, いつも, みんな oder だれでも.",structure:["Kurzform + とはかぎらない","Nomen／な-Adjektiv + (だ) + とはかぎらない"],examples:[{jp:"高[たか]い料理[りょうり]がおいしいとは限[かぎ]らない。",de:"Teures Essen ist nicht unbedingt lecker.",en:"Expensive food is not necessarily tasty."},{jp:"日本人[にほんじん]がみんな漢字[かんじ]に強[つよ]いとは限[かぎ]りません。",de:"Nicht alle Japaner sind unbedingt gut in Kanji.",en:"Not all Japanese people are necessarily good at kanji."}],matches:[],tags:["verneinung","ausnahme"]},
  {id:"g-n3-ni-chigainai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜に違いない – ganz sicher, muss wohl",jp:"〜にちがいない",summary:"Eine feste Überzeugung des Sprechers aufgrund dessen, was er sieht oder spürt: „es besteht kein Zweifel, dass …“. Sicherer als だろう, dabei eher Intuition als はずだ, das auf Logik beruht. Vor allem Schriftsprache; im Gespräch sagt man きっと〜とおもう. Nomen sowie な-Adjektive stehen direkt davor, ohne だ.",structure:["Kurzform + にちがいない","Nomen／な-Adjektiv + にちがいない"],examples:[{jp:"電気[でんき]が消[き]えている。もう寝[ね]たに違[ちが]いない。",de:"Das Licht ist aus. Er ist bestimmt schon ins Bett gegangen.",en:"The lights are off. He must have gone to bed already."},{jp:"あの人[ひと]は田中[たなか]さんのお兄[にい]さんに違[ちが]いない。顔[かお]がそっくりだ。",de:"Der Mann dort muss Herrn Tanakas älterer Bruder sein. Sie sehen sich zum Verwechseln ähnlich.",en:"That man must be Mr Tanaka's older brother. They look exactly alike."}],matches:[],tags:["vermutung","gewissheit"]},
  {id:"g-n3-you-na-ki-ga-suru",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ような気がする – ich habe das Gefühl, dass",jp:"〜ようなきがする",summary:"Ein vager Eindruck ohne klaren Beweis: „irgendwie kommt es mir so vor, als …“. Weicher, weniger sicher als とおもう. In der Umgangssprache lässt man ような oft weg: 〜きがする.",structure:["Kurzform + ようなきがする","Nomen + の + ようなきがする","な-Adjektiv + な + ようなきがする"],examples:[{jp:"あの人[ひと]にはどこかで会[あ]ったような気[き]がします。",de:"Ich habe das Gefühl, dass ich diesen Menschen schon irgendwo getroffen habe.",en:"I have a feeling that I have met that person somewhere."},{jp:"今日[きょう]はいいことがあるような気[き]がする。",de:"Ich habe das Gefühl, dass heute etwas Schönes passiert.",en:"I have a feeling that something good will happen today."}],matches:[],tags:["vermutung","gefühl"]},
  {id:"g-n3-nai-koto-wa-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ないことはない – es ist nicht so, dass nicht; geht schon, aber",jp:"〜ないことはない",summary:"Eine doppelte Verneinung, die ein zögerliches Ja ergibt: „es ist nicht unmöglich“, „ich kann schon, aber …“. Der Sprecher räumt etwas ein, hält sich dabei aber zurück; meist folgt ein Vorbehalt. ないこともない ist noch etwas schwächer.",structure:["ない-Form + ことはない","い-Adjektiv: 〜くない + ことはない","Nomen／な-Adjektiv + でない + ことはない"],examples:[{jp:"辛[から]い物[もの]は食[た]べられないことはないが、あまり好[す]きではない。",de:"Es ist nicht so, dass ich Scharfes nicht essen kann, aber ich mag es nicht besonders.",en:"It is not that I cannot eat spicy food, but I do not like it much."},{jp:"走[はし]れば、間[ま]に合[あ]わないことはないでしょう。",de:"Wenn wir rennen, ist es nicht ausgeschlossen, dass wir es noch schaffen.",en:"If we run, it is not impossible to make it in time."}],matches:[],tags:["verneinung","möglichkeit"]},
  {id:"g-n3-zu-ni-wa-irarenai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ずにはいられない – nicht anders können als",jp:"〜ずにはいられない",summary:"Sagt, dass ein Gefühl oder Drang so stark ist, dass man sich nicht zurückhalten kann: Man tut es, auch wenn man es zu lassen versucht. Man verwendet es für sich selbst (bei anderen hängt man そうだ oder ようだ an). ずに ist die schriftsprachliche Form; im Alltag sagt man ないではいられない.",structure:["ない-Form ohne ない + ずにはいられない","する → せずにはいられない"],examples:[{jp:"この映画[えいが]を見[み]ると、泣[な]かずにはいられない。",de:"Wenn ich diesen Film sehe, muss ich einfach weinen.",en:"When I watch this film, I cannot help crying."},{jp:"困[こま]っている人[ひと]を見[み]ると、助[たす]けずにはいられません。",de:"Wenn ich jemanden in Not sehe, kann ich nicht anders als helfen.",en:"When I see someone in trouble, I cannot help but help them."}],matches:[],tags:["gefühl","drang"]},
  {id:"g-n3-you-to-suru",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ようとする – versuchen zu; gerade … wollen",jp:"〜ようとする",summary:"Volitionalform + とする beschreibt den Moment, in dem man sich bemüht, etwas zu tun („versuchen“, oft ohne Erfolg), oder den Moment unmittelbar bevor etwas geschieht („im Begriff sein“). てみる ist etwas anderes: Dort tut man es tatsächlich, um zu sehen, wie es ist.",structure:["Volitionalform + とする","Volitionalform + としたとき"],examples:[{jp:"重[おも]い箱[はこ]を持[も]ち上[あ]げようとしたが、動[うご]かなかった。",de:"Ich habe versucht, die schwere Kiste hochzuheben, aber sie hat sich nicht bewegt.",en:"I tried to lift the heavy box, but it did not move."},{jp:"出[で]かけようとしたとき、電話[でんわ]が鳴[な]った。",de:"Gerade als ich losgehen wollte, klingelte das Telefon.",en:"Just as I was about to go out, the phone rang."}],matches:[],tags:["volitional","versuch"]},
  {id:"g-n3-you-to-shinai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ようとしない – macht keine Anstalten zu",jp:"〜ようとしない",summary:"Sagt, dass jemand überhaupt keinen Willen zeigt, etwas zu tun, meist in kritischem Ton. Man verwendet es für andere Personen, nicht für sich selbst.",structure:["Volitionalform + としない"],examples:[{jp:"弟[おとうと]は野菜[やさい]を食[た]べようとしない。",de:"Mein kleiner Bruder will Gemüse nicht einmal probieren.",en:"My younger brother will not even try to eat vegetables."},{jp:"彼[かれ]は自分[じぶん]の間違[まちが]いを認[みと]めようとしません。",de:"Er will seine eigenen Fehler einfach nicht eingestehen.",en:"He refuses to admit his own mistakes."}],matches:[],tags:["volitional","verneinung"]},
  {id:"g-n3-sou-mo-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜そうもない／〜そうにない – sieht nicht danach aus, dass",jp:"〜そうもない／〜そうにない",summary:"Die Verneinung von そうだ („sieht so aus, als würde“) bei Verben: Nach der Lage zu urteilen deutet nichts darauf hin, dass etwas geschieht. Steht oft mit Potentialverben: „es sieht nicht so aus, als könnte ich …“.",structure:["Verbstamm (ます-Stamm) + そうもない","Verbstamm (ます-Stamm) + そうにない"],examples:[{jp:"雨[あめ]はまだやみそうもない。",de:"Es sieht nicht so aus, als würde der Regen bald aufhören.",en:"It does not look as if the rain will stop any time soon."},{jp:"仕事[しごと]が多[おお]くて、今日[きょう]は早[はや]く帰[かえ]れそうにありません。",de:"Ich habe so viel Arbeit, dass ich heute wohl kaum früh nach Hause komme.",en:"I have so much work that I am unlikely to get home early today."}],matches:[],tags:["vermutung","verneinung"]},
  {id:"g-n3-ba-ii",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ばいい – du solltest einfach, es genügt, wenn",jp:"〜ばいい",summary:"ば-Form + いい nennt eine einfache Lösung: „es ist gut, wenn du …“, „mach doch einfach …“. Mit einem Fragewort bittet man um Rat (どうすればいいですか). 〜ばいいのに wünscht, dass jemand etwas täte. たらいい bedeutet dasselbe, ist aber etwas lockerer.",structure:["ば-Form + いい","Fragewort + ば-Form + いいですか"],examples:[{jp:"分[わ]からないときは、先生[せんせい]に聞[き]けばいいですよ。",de:"Wenn du etwas nicht verstehst, frag einfach den Lehrer.",en:"When you do not understand, you can just ask the teacher."},{jp:"この漢字[かんじ]は何[なん]と読[よ]めばいいですか。",de:"Wie soll ich dieses Kanji lesen?",en:"How should I read this kanji?"}],matches:[],tags:["rat","bedingung"]},
  {id:"g-n3-te-mo-kamawanai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜てもかまわない – es macht nichts, wenn; ich habe nichts dagegen",jp:"〜てもかまわない",summary:"Erteilt eine Erlaubnis oder bittet darum wie てもいい, aber etwas förmlicher, zurückhaltender: „es stört mich nicht, wenn …“. 〜なくてもかまわない bedeutet „man muss nicht unbedingt“.",structure:["て-Form + もかまわない","い-Adjektiv: 〜くてもかまわない","Nomen／な-Adjektiv + でもかまわない","ない-Form: 〜なくてもかまわない"],examples:[{jp:"ここに荷物[にもつ]を置[お]いてもかまいませんか。",de:"Stört es Sie, wenn ich mein Gepäck hier abstelle?",en:"Do you mind if I put my luggage here?"},{jp:"返事[へんじ]は明日[あした]でもかまいません。",de:"Die Antwort kann gern auch erst morgen kommen.",en:"I do not mind if you answer tomorrow."}],matches:[],tags:["erlaubnis"]},
  {id:"g-n3-te-goran",type:"grammar",source:"JLPT N3",level:"N3",title:"〜てごらん – versuch mal, schau mal",jp:"〜てごらん",summary:"Eine sanfte Aufforderung, etwas auszuprobieren, wie てみなさい. So spricht man mit Kindern, Schülern oder Jüngeren – nie mit Höhergestellten. Die vollere Form ist てごらんなさい.",structure:["て-Form + ごらん","て-Form + ごらんなさい"],examples:[{jp:"もう一度[いちど]ゆっくり読[よ]んでごらん。",de:"Lies es noch einmal langsam.",en:"Try reading it once more, slowly."},{jp:"窓[まど]の外[そと]を見[み]てごらん。雪[ゆき]が降[ふ]っているよ。",de:"Schau mal aus dem Fenster. Es schneit!",en:"Look out of the window. It is snowing!"}],matches:[],tags:["aufforderung","umgangssprache"]},
  {id:"g-n3-kke",type:"grammar",source:"JLPT N3",level:"N3",title:"〜っけ – wie war das noch gleich?",jp:"〜っけ",summary:"Eine lockere Satzendung für etwas, das man einmal wusste, an das man sich aber nicht mehr genau erinnert. Man fragt den anderen oder sich selbst. Auch bei Gegenwärtigem steht oft die Vergangenheit (なんだったっけ). Höflich: でしたっけ, ましたっけ.",structure:["Kurzform + っけ","Nomen／な-Adjektiv + だ／だった + っけ","Höflich: 〜でしたっけ／〜ましたっけ"],examples:[{jp:"会議[かいぎ]は何時[なんじ]からだっけ。",de:"Um wie viel Uhr fängt die Besprechung noch mal an?",en:"What time does the meeting start again?"},{jp:"あの店[みせ]、月曜日[げつようび]は休[やす]みでしたっけ。",de:"Der Laden dort – hatte der montags nicht zu?",en:"That shop – was it closed on Mondays?"}],matches:[],tags:["frage","umgangssprache"]},
  {id:"g-n3-n-datte",type:"grammar",source:"JLPT N3",level:"N3",title:"〜んだって – ich habe gehört, dass",jp:"〜んだって",summary:"Die lockere Art weiterzugeben, was man gehört hat, unter Freunden oder in der Familie; das höfliche Gegenstück ist そうです. Mit steigender Satzmelodie fragt man nach: „Ich habe gehört, dass …, stimmt das?“.",structure:["Kurzform + んだって","Nomen／な-Adjektiv + なんだって"],examples:[{jp:"田中[たなか]さん、来月[らいげつ]結婚[けっこん]するんだって。",de:"Tanaka heiratet nächsten Monat, habe ich gehört.",en:"I heard that Tanaka is getting married next month."},{jp:"あの映画[えいが]、とても面白[おもしろ]いんだって。",de:"Der Film soll total interessant sein.",en:"They say that film is really interesting."}],matches:[],tags:["hörensagen","umgangssprache"]},
  {id:"g-n3-furi-o-suru",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ふりをする – so tun, als ob",jp:"〜ふりをする",summary:"Sagt, dass jemand sich so verhält, als wäre etwas der Fall, obwohl es nicht stimmt.",structure:["Kurzform + ふりをする","Nomen + の + ふりをする","な-Adjektiv + な + ふりをする"],examples:[{jp:"弟[おとうと]は寝[ね]ているふりをしている。",de:"Mein kleiner Bruder tut so, als würde er schlafen.",en:"My younger brother is pretending to be asleep."},{jp:"知[し]っているのに、知[し]らないふりをした。",de:"Obwohl ich es wusste, tat ich so, als wüsste ich nichts.",en:"Although I knew, I pretended not to know."}],matches:[],tags:["vortäuschen"]},
  {id:"g-n3-de-yuumei",type:"grammar",source:"JLPT N3",level:"N3",title:"〜は〜で有名だ – für etwas berühmt sein",jp:"〜は〜でゆうめいだ",summary:"A は B でゆうめいだ: A ist für B berühmt. で nennt den Grund für die Bekanntheit. Ein ganzer Satz braucht こと vor で. Vergleiche 〜としてゆうめいだ, „berühmt als …“.",structure:["Nomen は + Nomen + でゆうめいだ","Nomen は + Kurzform + ことでゆうめいだ"],examples:[{jp:"京都[きょうと]は古[ふる]いお寺[てら]で有名[ゆうめい]です。",de:"Kyōto ist für seine alten Tempel berühmt.",en:"Kyoto is famous for its old temples."},{jp:"この店[みせ]はラーメンがおいしいことで有名[ゆうめい]だ。",de:"Dieses Lokal ist für seine leckeren Rāmen bekannt.",en:"This restaurant is famous for its delicious ramen."}],matches:[],tags:["ausdruck"]},
  {id:"g-n3-ippou-da",type:"grammar",source:"JLPT N3",level:"N3",title:"〜一方だ – immer mehr, immer weiter",jp:"〜いっぽうだ",summary:"Mit einem Verb der Veränderung (ふえる, へる, わるくなる …) sagt es, dass eine Entwicklung nur in eine Richtung weitergeht, ohne aufzuhören. Meist geht es um unerwünschte Veränderungen; es klingt etwas förmlich. 〜ばかりだ wird genauso verwendet, allerdings nur für Veränderungen zum Schlechten.",structure:["Wörterbuchform + いっぽうだ","Wörterbuchform + ばかりだ"],examples:[{jp:"物[もの]の値段[ねだん]は上[あ]がる一方[いっぽう]だ。",de:"Die Preise steigen immer weiter.",en:"Prices just keep going up."},{jp:"この町[まち]の人口[じんこう]は減[へ]る一方[いっぽう]です。",de:"Die Einwohnerzahl dieser Stadt nimmt immer weiter ab.",en:"The population of this town keeps getting smaller."}],matches:[],tags:["veränderung","tendenz"]},
  {id:"g-n3-zu-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ずに – ohne zu",jp:"〜ずに",summary:"Bedeutet dasselbe wie ないで: B tun, ohne A zu tun, oder B statt A tun. ずに ist die schriftsprachlichere, etwas steifere Form. Aus する wird せずに.",structure:["ない-Form ohne ない + ずに (いかない → いかずに)","する → せずに"],examples:[{jp:"朝[あさ]ご飯[はん]を食[た]べずに学校[がっこう]へ行[い]きました。",de:"Ich bin ohne Frühstück zur Schule gegangen.",en:"I went to school without eating breakfast."},{jp:"辞書[じしょ]を使[つか]わずに、この本[ほん]を読[よ]んでみてください。",de:"Versuchen Sie bitte, dieses Buch zu lesen, ohne ein Wörterbuch zu benutzen.",en:"Please try reading this book without using a dictionary."}],matches:[],tags:["verneinung","schriftsprache"]},
  {id:"g-n3-mama",type:"grammar",source:"JLPT N3",level:"N3",title:"〜まま – so wie es ist, im unveränderten Zustand",jp:"〜まま",summary:"Sagt, dass ein Zustand unverändert bleibt, während etwas anderes geschieht – oft ein Zustand, den man vorher hätte ändern sollen (Schuhe noch an, Licht noch an). このまま／そのまま bedeutet „so, wie es ist“.",structure:["た-Form／ない-Form + まま","Nomen + の + まま","い-Adjektiv + まま, な-Adjektiv + な + まま"],examples:[{jp:"電気[でんき]をつけたまま寝[ね]てしまいました。",de:"Ich bin bei brennendem Licht eingeschlafen.",en:"I fell asleep with the light on."},{jp:"この野菜[やさい]は生[なま]のまま食[た]べられます。",de:"Dieses Gemüse kann man roh essen, so wie es ist.",en:"This vegetable can be eaten raw, just as it is."}],matches:[],tags:["zustand"]},
  {id:"g-n3-toori",type:"grammar",source:"JLPT N3",level:"N3",title:"〜とおり(に) – genau so, wie",jp:"〜とおり(に)",summary:"Sagt, dass etwas genau so getan wird oder eintritt, wie es jemand gesagt oder gedacht hat oder wie ein Plan oder Muster es vorgibt. Direkt nach einem Nomen wird es zu どおり.",structure:["Wörterbuchform／た-Form + とおり(に)","Nomen + の + とおり(に)","Nomen + どおり(に)"],examples:[{jp:"私[わたし]が言[い]うとおりに書[か]いてください。",de:"Schreiben Sie es bitte genau so, wie ich es sage.",en:"Please write it exactly as I say."},{jp:"試合[しあい]は予定[よてい]どおり十時[じゅうじ]に始[はじ]まりました。",de:"Das Spiel begann wie geplant um zehn Uhr.",en:"The match started at ten o'clock as planned."}],matches:[],tags:["art-und-weise"]},
  {id:"g-n3-to-shite",type:"grammar",source:"JLPT N3",level:"N3",title:"〜として – als, in der Rolle von",jp:"〜として",summary:"Nennt die Rolle, Stellung oder Kategorie, in der jemand handelt oder etwas gesehen wird. としては fügt einen Kontrast hinzu („ich als … jedenfalls“), としての steht vor einem Nomen.",structure:["Nomen + として","Nomen + としては／としても","Nomen + としての + Nomen"],examples:[{jp:"彼[かれ]は医者[いしゃ]として病院[びょういん]で働[はたら]いています。",de:"Er arbeitet als Arzt in einem Krankenhaus.",en:"He works at a hospital as a doctor."},{jp:"京都[きょうと]は古[ふる]い町[まち]として知[し]られている。",de:"Kyōto ist als alte Stadt bekannt.",en:"Kyoto is known as an old city."}],matches:[],tags:["partikel","rolle"]},
  {id:"g-n3-ni-totte",type:"grammar",source:"JLPT N3",level:"N3",title:"〜にとって – für, aus Sicht von",jp:"〜にとって",summary:"Nennt die Person oder Gruppe, aus deren Sicht ein Urteil gilt. Danach folgt eine Bewertung (たいせつだ, むずかしい, ひつようだ …), keine Handlung, auch kein Wort wie さんせい. Nicht verwechseln mit にたいして, das das Ziel einer Handlung oder Haltung nennt.",structure:["Nomen + にとって","Nomen + にとっては／にとっても"],examples:[{jp:"私[わたし]にとって、家族[かぞく]が一番[いちばん]大切[たいせつ]です。",de:"Für mich ist die Familie das Wichtigste.",en:"For me, family is the most important thing."},{jp:"この問題[もんだい]は子[こ]どもにとって難[むずか]しすぎる。",de:"Diese Aufgabe ist für Kinder zu schwer.",en:"This problem is too difficult for children."}],matches:[],tags:["partikel","sichtweise"]},
  {id:"g-n3-ni-tsuite",type:"grammar",source:"JLPT N3",level:"N3",title:"〜について – über, bezüglich",jp:"〜について",summary:"Nennt das Thema, über das jemand spricht, schreibt, nachdenkt, fragt oder etwas herausfindet. Vor einem Nomen wird es zu についての.",structure:["Nomen + について","Nomen + については／についても","Nomen + についての + Nomen"],examples:[{jp:"日本[にほん]の文化[ぶんか]について調[しら]べています。",de:"Ich recherchiere über die japanische Kultur.",en:"I am doing research about Japanese culture."},{jp:"この問題[もんだい]についての意見[いけん]を聞[き]かせてください。",de:"Bitte sagen Sie mir Ihre Meinung zu diesem Problem.",en:"Please let me hear your opinion about this problem."}],matches:[],tags:["partikel","thema"]},
  {id:"g-n3-ni-kanshite",type:"grammar",source:"JLPT N3",level:"N3",title:"〜に関して／〜に関する – bezüglich, in Bezug auf",jp:"〜にかんして／〜にかんする",summary:"Bedeutet dasselbe wie について, ist aber förmlicher; häufig in Nachrichten, im Geschäftsleben oder in amtlichen Texten. Vor einem Nomen verwendet man にかんする (oder にかんしての).",structure:["Nomen + にかんして","Nomen + にかんしては／にかんしても","Nomen + にかんする + Nomen"],examples:[{jp:"この事故[じこ]に関[かん]して、警察[けいさつ]が説明[せつめい]しました。",de:"Die Polizei hat sich zu diesem Unfall geäußert.",en:"The police gave an explanation regarding this accident."},{jp:"環境問題[かんきょうもんだい]に関[かん]する本[ほん]を読[よ]みました。",de:"Ich habe ein Buch über Umweltprobleme gelesen.",en:"I read a book on environmental problems."}],matches:[],tags:["partikel","thema","förmlich"]},
  {id:"g-n3-ni-oite",type:"grammar",source:"JLPT N3",level:"N3",title:"〜において／〜における – in, bei (förmlich)",jp:"〜において／〜における",summary:"Ein förmliches で: Es nennt den Ort, die Zeit, das Gebiet oder die Situation, in der etwas geschieht. Man begegnet ihm in Reden, Nachrichten oder geschriebenen Texten. Vor einem Nomen wird es zu における.",structure:["Nomen + において","Nomen + においては／においても","Nomen + における + Nomen"],examples:[{jp:"会議[かいぎ]は東京[とうきょう]において行[おこな]われます。",de:"Die Konferenz findet in Tōkyō statt.",en:"The conference will be held in Tokyo."},{jp:"日本[にほん]における外国人[がいこくじん]の数[かず]は増[ふ]えている。",de:"Die Zahl der Ausländer in Japan nimmt zu.",en:"The number of foreigners in Japan is increasing."}],matches:[],tags:["partikel","förmlich"]},
  {id:"g-n3-ni-yotte",type:"grammar",source:"JLPT N3",level:"N3",title:"〜によって／〜による – durch, wegen, je nach",jp:"〜によって／〜による",summary:"Ein eher förmlicher Ausdruck mit mehreren Verwendungen: das Mittel („durch, mittels“), die Ursache („wegen, infolge“), der Handelnde im Passivsatz – besonders der Urheber eines Werks – sowie „je nach“. In der letzten Bedeutung steht oft ちがう oder かわる: Fragewort + かは〜によってちがう, „was/wann … hängt von … ab“. Vor einem Nomen wird es zu による.",structure:["Nomen + によって／により","Nomen + による + Nomen","Fragewort … かは + Nomen + によってちがう"],examples:[{jp:"何[なに]を食[た]べるかは、国[くに]によって違[ちが]います。",de:"Was man isst, ist von Land zu Land verschieden.",en:"What people eat differs from country to country."},{jp:"この小説[しょうせつ]は有名[ゆうめい]な作家[さっか]によって書[か]かれました。",de:"Dieser Roman wurde von einem berühmten Schriftsteller geschrieben.",en:"This novel was written by a famous author."}],matches:[],tags:["partikel","ursache","förmlich"]},
  {id:"g-n3-ni-yoru-to",type:"grammar",source:"JLPT N3",level:"N3",title:"〜によると／〜によれば – laut, zufolge",jp:"〜によると／〜によれば",summary:"Nennt die Quelle einer Information. Der Satz endet dann auf eine Form des Hörensagens wie そうだ, らしい oder ということだ. Nicht verwechseln mit によって, das keine weitergegebene Information einleitet.",structure:["Nomen + によると","Nomen + によれば"],examples:[{jp:"天気予報[てんきよほう]によると、明日[あした]は雪[ゆき]が降[ふ]るそうです。",de:"Laut Wettervorhersage soll es morgen schneien.",en:"According to the weather forecast, it will snow tomorrow."},{jp:"友[とも]だちの話[はなし]によれば、あの店[みせ]は来月[らいげつ]閉[し]まるらしい。",de:"Wie mein Freund erzählt, macht der Laden dort wohl nächsten Monat zu.",en:"According to my friend, that shop is apparently closing next month."}],matches:[],tags:["partikel","hörensagen"]},
  {id:"g-n3-uchi-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜うちに – solange noch, bevor (es zu spät ist)",jp:"〜うちに",summary:"Man tut etwas, solange ein Zustand noch anhält, weil es später schwieriger oder unmöglich wird. Mit der ない-Form heißt es „bevor … passiert“. Zweite Verwendung: Während man A tut, verändert sich etwas, ohne dass man es merkt. Anders als bei あいだに schwingt bei うちに mit, dass die Gelegenheit danach vorbei ist.",structure:["Wörterbuchform／ている + うちに","ない-Form + うちに","い-Adjektiv + うちに／な-Adjektiv + な + うちに","Nomen + の + うちに"],examples:[{jp:"温[あたた]かいうちに食[た]べてください。",de:"Bitte essen Sie es, solange es warm ist.",en:"Please eat it while it is warm."},{jp:"暗[くら]くならないうちに帰[かえ]りましょう。",de:"Lass uns nach Hause gehen, bevor es dunkel wird.",en:"Let's go home before it gets dark."}],matches:[],tags:["zeit"]},
  {id:"g-n3-no-aida-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜間に – während, in der Zeit (zu einem Zeitpunkt)",jp:"〜間[あいだ]に",summary:"Etwas geschieht einmal oder wird abgeschlossen, irgendwann innerhalb eines Zeitraums. Ohne に bedeutet あいだ, dass die zweite Handlung den ganzen Zeitraum über andauert: vergleiche るすのあいだ、ねこのせわをした (die ganze Zeit) mit るすのあいだに、にもつがとどいた (in einem Moment).",structure:["Nomen + の + あいだに","Verb ている／Wörterbuchform + あいだに"],examples:[{jp:"夏休[なつやす]みの間[あいだ]に、本[ほん]を五冊[ごさつ]読[よ]みました。",de:"In den Sommerferien habe ich fünf Bücher gelesen.",en:"During the summer holidays I read five books."},{jp:"私[わたし]が出[で]かけている間[あいだ]に、荷物[にもつ]が届[とど]きました。",de:"Während ich unterwegs war, ist ein Paket angekommen.",en:"A parcel arrived while I was out."}],matches:[],tags:["zeit"]},
  {id:"g-n3-saichuu-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜最中に – mitten in, gerade als",jp:"〜最中[さいちゅう]に",summary:"Etwas ist gerade voll im Gange, als plötzlich etwas anderes passiert, meist eine unwillkommene Störung. Es ist stärker als ているとき und steht nur bei Handlungen, die eine gewisse Zeit dauern.",structure:["Nomen + の + さいちゅうに","Verb ている + さいちゅうに"],examples:[{jp:"会議[かいぎ]の最中[さいちゅう]に、電話[でんわ]が鳴[な]りました。",de:"Mitten in der Besprechung klingelte das Telefon.",en:"The phone rang right in the middle of the meeting."},{jp:"料理[りょうり]をしている最中[さいちゅう]に、友達[ともだち]が来[き]ました。",de:"Gerade als ich mitten beim Kochen war, kam ein Freund vorbei.",en:"A friend came just when I was in the middle of cooking."}],matches:[],tags:["zeit"]},
  {id:"g-n3-tochuu-de",type:"grammar",source:"JLPT N3",level:"N3",title:"〜途中で – unterwegs, mittendrin",jp:"〜途中[とちゅう]で",summary:"Etwas geschieht zwischen Anfang und Ziel: auf dem Weg zu einem Ort oder mitten in einer Tätigkeit, die dann oft nicht zu Ende geführt wird. Auf とちゅうで folgt eine Handlung oder ein Ereignis, auf とちゅうに etwas, das sich auf dem Weg befindet.",structure:["Wörterbuchform + とちゅうで","Nomen + の + とちゅうで"],examples:[{jp:"学校[がっこう]へ行[い]く途中[とちゅう]で、先生[せんせい]に会[あ]いました。",de:"Auf dem Weg zur Schule habe ich meinen Lehrer getroffen.",en:"I met my teacher on the way to school."},{jp:"映画[えいが]の途中[とちゅう]で寝[ね]てしまいました。",de:"Ich bin mitten im Film eingeschlafen.",en:"I fell asleep partway through the film."}],matches:[],tags:["zeit"]},
  {id:"g-n3-ta-totan",type:"grammar",source:"JLPT N3",level:"N3",title:"〜たとたん(に) – in dem Moment, als; kaum … da",jp:"〜たとたん(に)",summary:"Genau in dem Moment, als A geschah, passierte B, und B kam unerwartet. B ist etwas, das der Sprecher bemerkt hat, nicht etwas, das er absichtlich getan hat; Absichten, Bitten und Aufforderungen können deshalb nicht folgen.",structure:["Kurzform Vergangenheit + とたん(に)"],examples:[{jp:"窓[まど]を開[あ]けたとたん、虫[むし]が入[はい]ってきました。",de:"Kaum hatte ich das Fenster geöffnet, flog ein Insekt herein.",en:"The moment I opened the window, an insect flew in."},{jp:"立[た]ち上[あ]がったとたんに、頭[あたま]が痛[いた]くなりました。",de:"In dem Moment, als ich aufstand, bekam ich Kopfschmerzen.",en:"Just as I stood up, my head started to hurt."}],matches:[],tags:["zeit"]},
  {id:"g-n3-tabi-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜たびに – jedes Mal, wenn",jp:"〜たびに",summary:"Jedes einzelne Mal, wenn A geschieht, geschieht auch B. Es steht bei wiederholten Anlässen, nicht bei Dingen, die von Natur aus immer so sind (dafür nimmt man と).",structure:["Wörterbuchform + たびに","Nomen + の + たびに"],examples:[{jp:"この歌[うた]を聞[き]くたびに、高校時代[こうこうじだい]を思[おも]い出[だ]します。",de:"Jedes Mal, wenn ich dieses Lied höre, erinnere ich mich an meine Oberschulzeit.",en:"Every time I hear this song, I remember my high school days."},{jp:"父[ちち]は出張[しゅっちょう]のたびに、お土産[みやげ]を買[か]ってきます。",de:"Mein Vater bringt von jeder Dienstreise ein Mitbringsel mit.",en:"My father brings back a present every time he goes on a business trip."}],matches:[],tags:["zeit","wiederholung"]},
  {id:"g-n3-te-hajimete",type:"grammar",source:"JLPT N3",level:"N3",title:"〜てはじめて – erst als, erst nachdem",jp:"〜てはじめて",summary:"Erst nachdem man A erlebt hat, hat man B erkannt oder gekonnt; vorher war es nicht so. Danach steht typischerweise わかる, きづく, しる oder eine ähnliche Erkenntnis, keine Absicht oder Bitte.",structure:["て-Form + はじめて"],examples:[{jp:"病気[びょうき]になってはじめて、健康[けんこう]の大切[たいせつ]さがわかりました。",de:"Erst als ich krank wurde, habe ich verstanden, wie wichtig Gesundheit ist.",en:"Only after I became ill did I understand how important health is."},{jp:"一人[ひとり]で暮[く]らしてはじめて、親[おや]のありがたさを知[し]りました。",de:"Erst als ich allein lebte, wurde mir klar, wie viel ich meinen Eltern verdanke.",en:"It was not until I lived on my own that I realised how much I owe my parents."}],matches:[],tags:["zeit","te-form"]},
  {id:"g-n3-ue-de",type:"grammar",source:"JLPT N3",level:"N3",title:"〜上で – nachdem man erst …, auf der Grundlage von",jp:"〜上[うえ]で",summary:"Zuerst wird A ordentlich erledigt, dann folgt auf der Grundlage des Ergebnisses B. Es klingt überlegter und förmlicher als てから und ist in der Geschäfts- und Amtssprache häufig. Mit der Wörterbuchform (〜するうえで) heißt es „beim …, für …“.",structure:["Kurzform Vergangenheit + うえで","Nomen + の + うえで","Wörterbuchform + うえで (beim …)"],examples:[{jp:"家族[かぞく]と相談[そうだん]した上[うえ]で、お返事[へんじ]します。",de:"Ich gebe Ihnen Bescheid, nachdem ich es mit meiner Familie besprochen habe.",en:"I will give you my answer after talking it over with my family."},{jp:"よく考[かんが]えた上[うえ]で、決[き]めてください。",de:"Bitte entscheiden Sie erst, nachdem Sie gründlich nachgedacht haben.",en:"Please decide after thinking it over carefully."}],matches:[],tags:["zeit","förmlich"]},
  {id:"g-n3-tsuide-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ついでに – bei der Gelegenheit, wenn man schon dabei ist",jp:"〜ついでに",summary:"Man nutzt die Gelegenheit von A, um auch B zu erledigen. A ist der eigentliche Zweck, B kommt nebenbei dazu, weil es sich anbietet. ついでに kann auch allein am Satzanfang stehen.",structure:["Wörterbuchform／Kurzform Vergangenheit + ついでに","Nomen + の + ついでに"],examples:[{jp:"買[か]い物[もの]のついでに、郵便局[ゆうびんきょく]に寄[よ]りました。",de:"Beim Einkaufen bin ich gleich noch bei der Post vorbeigegangen.",en:"While I was out shopping, I stopped by the post office."},{jp:"駅[えき]まで行[い]くついでに、この手紙[てがみ]を出[だ]してくれませんか。",de:"Wenn du sowieso zum Bahnhof gehst, könntest du diesen Brief für mich einwerfen?",en:"Since you are going to the station anyway, could you post this letter for me?"}],matches:[],tags:["gelegenheit"]},
  {id:"g-n3-okage-de",type:"grammar",source:"JLPT N3",level:"N3",title:"〜おかげで – dank",jp:"〜おかげで",summary:"Nennt die Ursache eines guten Ergebnisses und drückt Dankbarkeit aus. Bei einem schlechten Ergebnis nimmt man せいで; おかげで mit schlechtem Ergebnis ist ironisch. おかげさまで ist eine feste Wendung: „dank Ihnen / zum Glück“.",structure:["Nomen + の + おかげで","Kurzform + おかげで","な-Adjektiv + な + おかげで"],examples:[{jp:"先生[せんせい]のおかげで、試験[しけん]に合格[ごうかく]できました。",de:"Dank meiner Lehrerin habe ich die Prüfung bestanden.",en:"Thanks to my teacher, I was able to pass the exam."},{jp:"友達[ともだち]が手伝[てつだ]ってくれたおかげで、早[はや]く終[お]わりました。",de:"Dank der Hilfe meines Freundes war ich früh fertig.",en:"Thanks to my friend helping me, I finished early."}],matches:[],tags:["grund"]},
  {id:"g-n3-sei-de",type:"grammar",source:"JLPT N3",level:"N3",title:"〜せいで – wegen, schuld ist",jp:"〜せいで",summary:"Nennt die Ursache eines schlechten Ergebnisses und gibt ihr die Schuld. Es ist das negative Gegenstück zu おかげで. 〜せいか heißt „vielleicht weil …“, 〜せいにする „jemandem oder etwas die Schuld geben“.",structure:["Nomen + の + せいで","Kurzform + せいで","な-Adjektiv + な + せいで"],examples:[{jp:"雨[あめ]のせいで、試合[しあい]が中止[ちゅうし]になりました。",de:"Wegen des Regens wurde das Spiel abgesagt.",en:"Because of the rain, the match was cancelled."},{jp:"夜[よる]遅[おそ]くコーヒーを飲[の]んだせいで、眠[ねむ]れませんでした。",de:"Weil ich spätabends Kaffee getrunken habe, konnte ich nicht schlafen.",en:"I could not sleep because I drank coffee late at night."}],matches:[],tags:["grund"]},
  {id:"g-n3-tame-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ために – um zu, für; wegen",jp:"〜ため(に)",summary:"ために hat zwei Bedeutungen. Zweck: Mit der Wörterbuchform oder Nomen + の heißt es „um zu“, „für“ – das Ziel muss etwas sein, das man selbst steuern kann (bei Zuständen und Potentialformen nimmt man ように). Ursache: Nach einer Tatsache, die man nicht steuern kann (Vergangenheitsform, Zustand, Adjektiv, Ereignis-Nomen), heißt es „wegen“, „aufgrund von“ – sachlich und eher förmlich, wie in Nachrichten und Durchsagen.",structure:["Wörterbuchform + ため(に) (Zweck)","Nomen + の + ため(に) (Zweck oder Ursache)","Kurzform + ため(に) (Ursache)","な-Adjektiv + な + ため(に) (Ursache)"],examples:[{jp:"日本[にほん]で働[はたら]くために、日本語[にほんご]を勉強[べんきょう]しています。",de:"Ich lerne Japanisch, um in Japan zu arbeiten.",en:"I am studying Japanese in order to work in Japan."},{jp:"台風[たいふう]のために、電車[でんしゃ]が止[と]まりました。",de:"Wegen des Taifuns fuhren die Züge nicht mehr.",en:"The trains stopped because of the typhoon."}],matches:[],tags:["zweck","grund"]},
  {id:"g-n3-sono-tame",type:"grammar",source:"JLPT N3",level:"N3",title:"そのため(に) – deshalb, aus diesem Grund",jp:"そのため(に)",summary:"Eine Konjunktion am Satzanfang: Der Satz davor nennt die Ursache, dieser die Folge. Es ist förmlicher und sachlicher als だから und in Nachrichten und schriftlichen Erklärungen häufig. Es kann auch „zu diesem Zweck“ heißen.",structure:["Satz。そのため(に)、+ Satz"],examples:[{jp:"昨日[きのう]は大雪[おおゆき]でした。そのため、学校[がっこう]が休[やす]みになりました。",de:"Gestern hat es stark geschneit. Deshalb fiel die Schule aus.",en:"There was heavy snow yesterday. For that reason, school was closed."}],matches:[],tags:["konjunktion","grund","förmlich"]},
  {id:"g-n3-kekka",type:"grammar",source:"JLPT N3",level:"N3",title:"〜結果／その結果 – als Ergebnis, infolgedessen",jp:"〜結果[けっか]／その結果[けっか]",summary:"Sagt, was bei einer Handlung herausgekommen ist, ob gut oder schlecht. 〜たけっか und Nomen + のけっか verbinden Ursache und Ergebnis in einem Satz; そのけっか beginnt einen neuen Satz. Es klingt sachlich und ist typisch für Berichte und Nachrichten.",structure:["Kurzform Vergangenheit + けっか","Nomen + の + けっか","Satz。そのけっか、+ Satz"],examples:[{jp:"話[はな]し合[あ]った結果[けっか]、旅行[りょこう]は来月[らいげつ]にすることになりました。",de:"Als Ergebnis unserer Besprechung wurde beschlossen, die Reise nächsten Monat zu machen.",en:"As a result of our discussion, it was decided to make the trip next month."},{jp:"毎日[まいにち]練習[れんしゅう]しました。その結果[けっか]、試合[しあい]に勝[か]つことができました。",de:"Wir haben jeden Tag trainiert. Infolgedessen konnten wir das Spiel gewinnen.",en:"We practised every day. As a result, we were able to win the match."}],matches:[],tags:["ergebnis","konjunktion"]},
  {id:"g-n3-kuse-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜くせに – obwohl (vorwurfsvoll), und dabei",jp:"〜くせに",summary:"„Obwohl“, gesagt mit Kritik oder Verachtung gegenüber der Person, über die man spricht. Beide Satzteile haben dasselbe Subjekt. Es ist viel stärker und persönlicher als のに und passt nicht in höfliche Situationen.",structure:["Kurzform + くせに","Nomen + の + くせに","な-Adjektiv + な + くせに"],examples:[{jp:"彼[かれ]は自分[じぶん]では何[なに]もしないくせに、文句[もんく]ばかり言[い]います。",de:"Er selbst tut gar nichts und beschwert sich dabei ständig.",en:"He does nothing himself, and yet he does nothing but complain."},{jp:"本当[ほんとう]は知[し]っているくせに、教[おし]えてくれないんです。",de:"Eigentlich weiß sie es, und trotzdem sagt sie es mir nicht.",en:"She actually knows, and still she will not tell me."}],matches:[],tags:["gegensatz","umgangssprache"]},
  {id:"g-n3-nagara-mo",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ながら(も) – obwohl, wenn auch",jp:"〜ながらも",summary:"Hier bedeutet ながら nicht „gleichzeitig“, sondern „obwohl“: B gilt trotz des Zustands A. Es steht bei Zuständen (しっている, おもう, ざんねん, せまい) und klingt eher schriftlich. も verstärkt den Gegensatz.",structure:["Verbstamm (ます-Stamm) + ながら(も)","い-Adjektiv + ながら(も)","Nomen／な-Adjektiv + ながら(も)"],examples:[{jp:"狭[せま]いながらも、自分[じぶん]の部屋[へや]ができてうれしいです。",de:"Es ist zwar klein, aber ich freue mich, ein eigenes Zimmer zu haben.",en:"Small as it is, I am happy to have a room of my own."},{jp:"彼[かれ]は体[からだ]に悪[わる]いと知[し]りながらも、たばこをやめられません。",de:"Obwohl er weiß, dass es ungesund ist, kann er nicht mit dem Rauchen aufhören.",en:"Although he knows it is bad for his health, he cannot give up smoking."}],matches:[],tags:["gegensatz","schriftsprache"]},
  {id:"g-n3-wari-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜割に(は) – dafür, dass; im Verhältnis zu",jp:"〜わりに(は)",summary:"Das Ergebnis steht nicht im Verhältnis zu dem, was man nach A erwarten würde: besser oder schlechter als gedacht. Es folgt typischerweise auf Wörter für ein Maß wie ねだん, とし, たかい oder auf die Angabe, wie viel jemand getan hat.",structure:["Kurzform + わりに(は)","Nomen + の + わりに(は)","な-Adjektiv + な + わりに(は)"],examples:[{jp:"このレストランは値段[ねだん]のわりにおいしいです。",de:"Für den Preis schmeckt es in diesem Restaurant gut.",en:"This restaurant is good for the price."},{jp:"あまり勉強[べんきょう]しなかったわりには、いい点[てん]が取[と]れました。",de:"Dafür, dass ich kaum gelernt habe, habe ich eine gute Note bekommen.",en:"Considering that I hardly studied, I got a good mark."}],matches:[],tags:["gegensatz","vergleich"]},
  {id:"g-n3-ni-shite-wa",type:"grammar",source:"JLPT N3",level:"N3",title:"〜にしては – dafür, dass; für",jp:"〜にしては",summary:"Etwas ist anders, als man es bei A normalerweise erwarten würde. Es folgt auf eine konkrete Tatsache oder Kategorie (ein Anfänger, Mai, zehn Jahre Übung), während わりに auf Maß-Wörter folgt. Bei Adjektiven wird es nicht verwendet, Nomen stehen davor ohne だ.",structure:["Nomen + にしては","Verb Kurzform + にしては"],examples:[{jp:"彼[かれ]は初[はじ]めてにしては、とても上手[じょうず]でした。",de:"Für das erste Mal war er sehr gut.",en:"For a first time, he was very good."},{jp:"五月[ごがつ]にしては、今日[きょう]は暑[あつ]いですね。",de:"Für Mai ist es heute ganz schön heiß, oder?",en:"It is hot today for May, isn't it?"}],matches:[],tags:["gegensatz","vergleich"]},
  {id:"g-n3-ni-shite-mo",type:"grammar",source:"JLPT N3",level:"N3",title:"〜にしても – selbst wenn, auch wenn es so ist",jp:"〜にしても",summary:"Man lässt A als Tatsache oder Möglichkeit gelten, bleibt aber bei seinem Urteil B: „trotzdem …“. Oft leitet es Kritik oder Zweifel ein. それにしても am Satzanfang heißt „trotzdem, aber dennoch“.",structure:["Kurzform + にしても","Nomen／な-Adjektiv + にしても"],examples:[{jp:"忙[いそが]しいにしても、電話[でんわ]ぐらいはできるでしょう。",de:"Auch wenn du viel zu tun hast, anrufen kannst du doch wenigstens, oder?",en:"Even if you are busy, you can at least make a phone call, can't you?"},{jp:"冗談[じょうだん]にしても、それはひどいです。",de:"Selbst wenn es ein Scherz sein sollte, das ist gemein.",en:"Even if it was meant as a joke, that is awful."}],matches:[],tags:["einräumung"]},
  {id:"g-n3-tatoe-te-mo",type:"grammar",source:"JLPT N3",level:"N3",title:"たとえ〜ても – selbst wenn, auch wenn",jp:"たとえ〜ても",summary:"たとえ kündigt einen ても-Satz an und verstärkt ihn: Selbst im extremen oder unwahrscheinlichen Fall A ändert sich B nicht. Es zeigt einen festen Entschluss oder eine feste Überzeugung.",structure:["たとえ + Verb て-Form + も","たとえ + い-Adjektiv 〜くても","たとえ + Nomen／な-Adjektiv + でも"],examples:[{jp:"たとえ雨[あめ]が降[ふ]っても、試合[しあい]は行[おこな]います。",de:"Selbst wenn es regnet, findet das Spiel statt.",en:"Even if it rains, the match will be held."},{jp:"たとえ高[たか]くても、いい物[もの]を買[か]いたいです。",de:"Auch wenn es teuer ist, möchte ich etwas Gutes kaufen.",en:"Even if it is expensive, I want to buy something good."}],matches:[],tags:["einräumung","bedingung"]},
  {id:"g-n3-ikura-donnani-te-mo",type:"grammar",source:"JLPT N3",level:"N3",title:"いくら〜ても／どんなに〜ても – egal wie (sehr), so viel auch",jp:"いくら〜ても／どんなに〜ても",summary:"Wie viel oder wie sehr A auch zutrifft, das Ergebnis B bleibt gleich. いくら bezieht sich meist auf Menge und Wiederholung (wie viel, wie oft), どんなに auf den Grad (wie sehr); in vielen Sätzen geht beides. Mit Nomen: いくらこどもでも „auch wenn er noch ein Kind ist“.",structure:["いくら／どんなに + Verb て-Form + も","いくら／どんなに + い-Adjektiv 〜くても","いくら／どんなに + Nomen／な-Adjektiv + でも"],examples:[{jp:"いくら呼[よ]んでも、返事[へんじ]がありません。",de:"So oft ich auch rufe, es kommt keine Antwort.",en:"No matter how many times I call, there is no answer."},{jp:"どんなに忙[いそが]しくても、朝[あさ]ご飯[はん]は食[た]べます。",de:"Egal wie viel ich zu tun habe, ich frühstücke.",en:"No matter how busy I am, I eat breakfast."}],matches:[],tags:["einräumung"]},
  {id:"g-n3-to-shitara",type:"grammar",source:"JLPT N3",level:"N3",title:"〜としたら／〜とすれば – angenommen, falls es so wäre",jp:"〜としたら／〜とすれば",summary:"Stellt eine Annahme auf: „Nehmen wir an, A stimmt – dann B“. A kann unwirklich oder einfach unbekannt sein. Auf とすると folgt meist eine logische Schlussfolgerung, auf としたら oder とすれば auch eine Frage, ein Wunsch oder eine Meinung.",structure:["Kurzform + としたら／とすれば／とすると","Nomen／な-Adjektiv + だ + としたら"],examples:[{jp:"宝[たから]くじが当[あ]たったとしたら、何[なに]を買[か]いますか。",de:"Angenommen, du würdest im Lotto gewinnen, was würdest du kaufen?",en:"Supposing you won the lottery, what would you buy?"},{jp:"行[い]くとしたら、来週[らいしゅう]の土曜日[どようび]がいいです。",de:"Wenn ich hingehen sollte, dann wäre nächster Samstag gut.",en:"If I were to go, next Saturday would be good."}],matches:[],tags:["bedingung","annahme"]},
  {id:"g-n3-moshimo",type:"grammar",source:"JLPT N3",level:"N3",title:"もしも – falls (wirklich einmal), angenommen",jp:"もしも〜たら",summary:"Ein verstärktes もし. Es steht am Anfang eines Bedingungssatzes und betont, dass der Fall nur gedacht, unwahrscheinlich oder ernst ist. もしものとき heißt „im Notfall“.",structure:["もしも + 〜たら／〜ば／〜なら","もしも + 〜ても"],examples:[{jp:"もしも地震[じしん]が起[お]きたら、どうしますか。",de:"Was würden Sie tun, falls es ein Erdbeben gäbe?",en:"What would you do if there were an earthquake?"},{jp:"もしも生[う]まれ変[か]われるなら、鳥[とり]になりたいです。",de:"Wenn ich noch einmal geboren werden könnte, wäre ich gern ein Vogel.",en:"If I could be born again, I would like to be a bird."}],matches:[],tags:["bedingung","adverb"]},
  {id:"g-n3-sae-ba",type:"grammar",source:"JLPT N3",level:"N3",title:"〜さえ〜ば – wenn nur, solange nur",jp:"〜さえ〜ば",summary:"Nennt die eine Bedingung, die genügt: Wenn nur A erfüllt ist, braucht es für B nichts weiter. さえ ersetzt が oder を und steht direkt an dem Wort, auf das es ankommt.",structure:["Nomen + さえ + ば-Form","Verbstamm (ます-Stamm) + さえ + すれば","て-Form + さえ + いれば","い-Adjektiv 〜く／な-Adjektiv 〜で + さえ + あれば"],examples:[{jp:"時間[じかん]さえあれば、旅行[りょこう]に行[い]きたいです。",de:"Wenn ich nur Zeit hätte, würde ich gern verreisen.",en:"If only I had the time, I would like to go on a trip."},{jp:"この薬[くすり]を飲[の]みさえすれば、すぐ治[なお]ります。",de:"Sie müssen nur dieses Medikament nehmen, dann sind Sie bald wieder gesund.",en:"As long as you take this medicine, you will get better soon."}],matches:[],tags:["bedingung","partikel"]},
  {id:"g-n3-ba-hodo",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ば〜ほど – je … desto",jp:"〜ば〜ほど",summary:"Je mehr A zunimmt, desto mehr nimmt auch B zu (oder ab). Dasselbe Wort wird zweimal gesagt: erst in der ば-Form, dann in der Wörterbuchform + ほど. Beim Sprechen fällt der ば-Teil oft weg: れんしゅうするほど.",structure:["Verb ば-Form + Wörterbuchform + ほど","い-Adjektiv: 〜ければ + 〜い + ほど","な-Adjektiv: 〜なら + 〜な + ほど"],examples:[{jp:"日本語[にほんご]は勉強[べんきょう]すればするほど、面白[おもしろ]くなります。",de:"Je mehr man Japanisch lernt, desto interessanter wird es.",en:"The more you study Japanese, the more interesting it gets."},{jp:"駅[えき]に近[ちか]ければ近[ちか]いほど、家賃[やちん]が高[たか]いです。",de:"Je näher am Bahnhof, desto höher ist die Miete.",en:"The closer to the station, the higher the rent."}],matches:[],tags:["ausmaß","bedingung"]},
  {id:"g-n3-hodo",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ほど – so sehr, dass; in dem Maße",jp:"〜ほど",summary:"Zeigt, wie extrem etwas ist, indem man ein Beispiel oder Bild für das Ausmaß nennt: „zum Sterben müde“. Es ähnelt くらい, aber ほど wird bei einem hohen Grad bevorzugt und klingt etwas förmlicher. Nach einer Zahl heißt es „ungefähr“.",structure:["Verb Kurzform + ほど","い-Adjektiv／〜たい + ほど","Nomen + ほど"],examples:[{jp:"昨日[きのう]は歩[ある]けないほど足[あし]が痛[いた]かったです。",de:"Gestern taten mir die Beine so weh, dass ich nicht laufen konnte.",en:"Yesterday my legs hurt so much that I could not walk."},{jp:"今日[きょう]は死[し]ぬほど忙[いそが]しかった。",de:"Heute hatte ich wahnsinnig viel zu tun (zum Sterben viel).",en:"Today I was incredibly busy (busy to death)."}],matches:[],tags:["ausmaß"]},
  {id:"g-n3-hodo-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ほど〜ない – nicht so … wie",jp:"〜ほど〜ない",summary:"A erreicht den Grad von B nicht. Der Vergleichsmaßstab steht vor ほど, das Prädikat ist verneint. Das verwandte 〜ほど〜はない sagt, dass nichts an etwas herankommt: りょこうほどたのしいものはない „nichts macht so viel Spaß wie Reisen“.",structure:["Nomen + ほど + Verneinung","Verb Kurzform + ほど + Verneinung","Nomen + ほど + … + Nomen + は + ない"],examples:[{jp:"今年[ことし]の冬[ふゆ]は去年[きょねん]ほど寒[さむ]くないです。",de:"Dieser Winter ist nicht so kalt wie der letzte.",en:"This winter is not as cold as last year."},{jp:"試験[しけん]は思[おも]ったほど難[むずか]しくなかったです。",de:"Die Prüfung war nicht so schwer, wie ich gedacht hatte.",en:"The exam was not as difficult as I had thought."}],matches:[],tags:["ausmaß","vergleich"]},
  {id:"g-n3-kurai-extent",type:"grammar",source:"JLPT N3",level:"N3",title:"〜くらい／〜ぐらい – so sehr, dass; wenigstens",jp:"〜くらい／〜ぐらい",summary:"くらい kennst du nach Zahlen als „ungefähr“. Hier gibt es das Ausmaß durch ein Beispiel an („so …, dass ich weinen wollte“), wie ほど, aber umgangssprachlicher. Außerdem kann es etwas als Kleinigkeit hinstellen: „wenigstens …, so etwas Einfaches wie …“.",structure:["Verb Kurzform + くらい／ぐらい","い-Adjektiv／〜たい + くらい／ぐらい","Nomen + くらい／ぐらい"],examples:[{jp:"泣[な]きたいくらい痛[いた]かったです。",de:"Es tat so weh, dass ich hätte weinen können.",en:"It hurt so much that I wanted to cry."},{jp:"自分[じぶん]の部屋[へや]くらい、自分[じぶん]で掃除[そうじ]しなさい。",de:"Wenigstens dein eigenes Zimmer putzt du bitte selbst.",en:"Clean your own room yourself, at least."}],matches:[],tags:["ausmaß","partikel"]},
  {id:"g-n3-dake-as-much-as",type:"grammar",source:"JLPT N3",level:"N3",title:"〜だけ – so viel wie",jp:"〜だけ",summary:"Hier heißt だけ nicht „nur“, sondern bezeichnet das volle Ausmaß: so viel man will, so viel wie möglich. Es steht nach Potentialverben, 〜たい, すきな, ほしい und ähnlichen Wörtern. できるだけ heißt „so … wie möglich“.",structure:["Potentialverb (Wörterbuchform) + だけ","〜たい + だけ","すきな／ほしい + だけ"],examples:[{jp:"好[す]きなだけ食[た]べてください。",de:"Essen Sie bitte, so viel Sie mögen.",en:"Please eat as much as you like."},{jp:"できるだけ早[はや]く返事[へんじ]をください。",de:"Bitte antworten Sie so bald wie möglich.",en:"Please reply as soon as possible."}],matches:[],tags:["ausmaß","partikel"]},
  {id:"g-n3-amari",type:"grammar",source:"JLPT N3",level:"N3",title:"〜あまり – vor lauter, so sehr … dass",jp:"〜(の)あまり",summary:"Ein Gefühl oder Zustand ist so stark, dass es zu einem ungewöhnlichen, meist unerwünschten Ergebnis führt. Es folgt auf Wörter für Gefühle und seelische Zustände und klingt eher schriftlich. Es ist nicht das bekannte あまり〜ない („nicht sehr“): Hier steht あまり hinter dem Wort, und der Satz ist bejaht.",structure:["Nomen + の + あまり","Verb Wörterbuchform／Kurzform Vergangenheit + あまり","い-Adjektiv 〜さ + の + あまり (うれしさのあまり)"],examples:[{jp:"緊張[きんちょう]のあまり、何[なに]も話[はな]せませんでした。",de:"Vor lauter Aufregung konnte ich kein Wort sagen.",en:"I was so nervous that I could not say anything."},{jp:"心配[しんぱい]するあまり、何度[なんど]も電話[でんわ]をかけてしまいました。",de:"Ich machte mir solche Sorgen, dass ich immer wieder angerufen habe.",en:"I was so worried that I ended up calling again and again."}],matches:[],tags:["ausmaß","grund","schriftsprache"]},
  {id:"g-n3-amari-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"あまりに(も) – allzu, so … dass",jp:"あまりに(も)",summary:"Ein Adverb vor einem Adjektiv oder Verb: Der Grad geht über das Normale hinaus, was oft eine Folge hat. も verstärkt. Vor einem Nomen wird es zu あまりの: あまりのあつさに „wegen der extremen Hitze“.",structure:["あまりに(も) + Adjektiv／Verb","あまりの + Nomen + に"],examples:[{jp:"この問題[もんだい]はあまりにも難[むずか]しくて、だれも答[こた]えられませんでした。",de:"Diese Aufgabe war so schwer, dass niemand sie lösen konnte.",en:"This question was so difficult that nobody could answer it."},{jp:"あまりの暑[あつ]さに、何[なに]もしたくありません。",de:"Es ist so heiß, dass ich zu gar nichts Lust habe.",en:"It is so hot that I do not feel like doing anything."}],matches:[],tags:["ausmaß","adverb"]},
  {id:"g-n3-dokoro-ka",type:"grammar",source:"JLPT N3",level:"N3",title:"〜どころか – weit entfernt von; geschweige denn",jp:"〜どころか",summary:"Weist eine Erwartung entschieden zurück. Entweder ist die Wirklichkeit das Gegenteil von A („statt besser wurde es schlimmer“), oder A kommt gar nicht in Frage, weil nicht einmal etwas viel Leichteres zutrifft („er kann nicht einmal Hiragana lesen, geschweige denn Kanji“).",structure:["Nomen + どころか","Kurzform + どころか","な-Adjektiv + (な) + どころか"],examples:[{jp:"薬[くすり]を飲[の]んだのに、よくなるどころか、もっと悪[わる]くなりました。",de:"Obwohl ich Medizin genommen habe, wurde es nicht besser, sondern im Gegenteil noch schlimmer.",en:"Although I took medicine, far from getting better, I got worse."},{jp:"彼[かれ]は漢字[かんじ]どころか、ひらがなも読[よ]めません。",de:"Er kann nicht einmal Hiragana lesen, geschweige denn Kanji.",en:"He cannot even read hiragana, let alone kanji."}],matches:[],tags:["gegensatz","betonung"]},
  {id:"g-n3-bakari-de-naku",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ばかりでなく – nicht nur …, sondern auch",jp:"〜ばかりでなく",summary:"Fügt zu A noch etwas hinzu; im zweiten Teil steht meist も, さえ oder まで. Die Bedeutung ist dieselbe wie bei だけでなく, es klingt aber etwas förmlicher, eher schriftlich.",structure:["Nomen + ばかりでなく","Kurzform + ばかりでなく","な-Adjektiv + な + ばかりでなく"],examples:[{jp:"彼女[かのじょ]は英語[えいご]ばかりでなく、中国語[ちゅうごくご]も話[はな]せます。",de:"Sie spricht nicht nur Englisch, sondern auch Chinesisch.",en:"She can speak not only English but also Chinese."},{jp:"この店[みせ]は安[やす]いばかりでなく、味[あじ]もいいです。",de:"Dieses Lokal ist nicht nur günstig, es schmeckt dort auch gut.",en:"This restaurant is not only cheap, the food tastes good as well."}],matches:[],tags:["ergänzung","förmlich"]},
  {id:"g-n3-dake-de-naku",type:"grammar",source:"JLPT N3",level:"N3",title:"〜だけでなく – nicht nur …, sondern auch",jp:"〜だけでなく",summary:"Die alltägliche Art, „nicht nur A, sondern auch B“ zu sagen; B steht meist mit も. Im Gespräch wird daraus だけじゃなくて.",structure:["Nomen + だけでなく","Kurzform + だけでなく","な-Adjektiv + な + だけでなく"],examples:[{jp:"肉[にく]だけでなく、野菜[やさい]も食[た]べなさい。",de:"Iss nicht nur Fleisch, sondern auch Gemüse.",en:"Eat not just meat but vegetables too."},{jp:"彼[かれ]は歌[うた]が上手[じょうず]なだけでなく、ダンスもできます。",de:"Er kann nicht nur gut singen, sondern auch tanzen.",en:"He is not only good at singing, he can dance as well."}],matches:[],tags:["ergänzung"]},
  {id:"g-n3-wa-mochiron",type:"grammar",source:"JLPT N3",level:"N3",title:"〜はもちろん – natürlich …, aber auch; ganz zu schweigen von",jp:"〜はもちろん",summary:"A versteht sich von selbst, und B gilt ebenfalls. A ist das naheliegende Beispiel, B das erwähnenswerte; B steht mit も.",structure:["Nomen + はもちろん + Nomen + も"],examples:[{jp:"このアニメは子[こ]どもはもちろん、大人[おとな]にも人気[にんき]があります。",de:"Dieser Anime ist natürlich bei Kindern beliebt, aber auch bei Erwachsenen.",en:"This anime is popular with children, of course, but also with adults."},{jp:"彼[かれ]は平日[へいじつ]はもちろん、週末[しゅうまつ]も働[はたら]いています。",de:"Er arbeitet nicht nur unter der Woche, sondern selbstverständlich auch am Wochenende.",en:"He works on weekends, not to mention weekdays."}],matches:[],tags:["ergänzung"]},
  {id:"g-n3-wo-hajime",type:"grammar",source:"JLPT N3",level:"N3",title:"〜をはじめ – allen voran, angefangen bei",jp:"〜をはじめ(として)",summary:"Nennt zuerst das typischste oder wichtigste Beispiel einer Gruppe, danach folgt der Rest der Gruppe. Es ist förmlich, häufig in Reden, Briefen sowie schriftlichen Beschreibungen.",structure:["Nomen + をはじめ(として)","Nomen + をはじめとする + Nomen"],examples:[{jp:"京都[きょうと]には、金閣寺[きんかくじ]をはじめ、有名[ゆうめい]なお寺[てら]がたくさんあります。",de:"In Kyōto gibt es viele berühmte Tempel, allen voran den Kinkaku-ji.",en:"In Kyoto there are many famous temples, starting with Kinkaku-ji."},{jp:"校長先生[こうちょうせんせい]をはじめ、先生方[せんせいがた]に大変[たいへん]お世話[せわ]になりました。",de:"Dem Schulleiter sowie allen anderen Lehrerinnen und Lehrern bin ich zu großem Dank verpflichtet.",en:"I am very grateful to the headmaster and all the other teachers."}],matches:[],tags:["beispiel","förmlich"]},
  {id:"g-n3-kawari-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜代わりに – anstelle von, statt; als Gegenleistung",jp:"〜代[か]わりに",summary:"Drei verwandte Verwendungen: B geschieht an Stelle von A („statt“), B ist die Gegenleistung für A („dafür“), oder ein Nachteil wird durch einen Vorteil ausgeglichen („es ist teuer, aber dafür …“).",structure:["Nomen + の + かわりに","Kurzform + かわりに","な-Adjektiv + な + かわりに"],examples:[{jp:"今日[きょう]は父[ちち]の代[か]わりに、私[わたし]が運転[うんてん]します。",de:"Heute fahre ich anstelle meines Vaters.",en:"Today I will drive instead of my father."},{jp:"日本語[にほんご]を教[おし]えてもらう代[か]わりに、英語[えいご]を教[おし]えています。",de:"Dafür, dass man mir Japanisch beibringt, unterrichte ich Englisch.",en:"In exchange for being taught Japanese, I teach English."}],matches:[],tags:["ersatz"]},
  {id:"g-n3-ni-kawatte",type:"grammar",source:"JLPT N3",level:"N3",title:"〜に代わって – anstelle von, stellvertretend für",jp:"〜に代[か]わって",summary:"Jemand handelt für eine andere Person, oder etwas Neues ersetzt das, was vorher verwendet wurde. Es steht nur nach Nomen, förmlicher als のかわりに; にかわり ist noch steifer.",structure:["Nomen + にかわって","Nomen + にかわり (förmlicher)"],examples:[{jp:"社長[しゃちょう]に代[か]わって、私[わたし]がごあいさつします。",de:"Stellvertretend für den Firmenchef möchte ich Sie begrüßen.",en:"I would like to say a few words on behalf of the company president."},{jp:"手紙[てがみ]に代[か]わって、メールが使[つか]われるようになりました。",de:"Anstelle von Briefen werden inzwischen E-Mails verwendet.",en:"E-mail has come to be used in place of letters."}],matches:[],tags:["ersatz","förmlich"]},
  {id:"g-n3-ippou-de",type:"grammar",source:"JLPT N3",level:"N3",title:"〜一方(で) – einerseits … andererseits, während",jp:"〜一方[いっぽう]で",summary:"Stellt zwei Seiten nebeneinander: zwei gegensätzliche Aspekte derselben Sache oder zwei entgegengesetzte Entwicklungen. いっぽう(で) kann auch einen neuen Satz beginnen. Nicht verwechseln mit 〜いっぽうだ am Satzende, das „immer mehr …“ bedeutet.",structure:["Kurzform + いっぽう(で)","な-Adjektiv + な + いっぽう(で)","Nomen + である + いっぽう(で)"],examples:[{jp:"この仕事[しごと]は大変[たいへん]な一方[いっぽう]で、とても楽[たの]しいです。",de:"Diese Arbeit ist anstrengend, macht aber andererseits sehr viel Spaß.",en:"This job is hard, but on the other hand it is a lot of fun."},{jp:"子[こ]どもの数[かず]が減[へ]る一方[いっぽう]で、お年寄[としよ]りは増[ふ]えています。",de:"Während die Zahl der Kinder sinkt, nimmt die der alten Menschen zu.",en:"While the number of children is falling, the number of elderly people is rising."}],matches:[],tags:["gegensatz"]},
  {id:"g-n3-ni-taishite",type:"grammar",source:"JLPT N3",level:"N3",title:"〜に対して – gegenüber; im Gegensatz zu",jp:"〜に対[たい]して",summary:"Zwei Verwendungen. Nach einem Nomen bezeichnet es die Person oder Sache, auf die sich eine Haltung, ein Gefühl oder eine Handlung richtet („gegenüber, zu“). Nach einem Satz + の stellt es zwei Dinge gegenüber („während, wohingegen“). Vor einem Nomen wird es zu にたいする.",structure:["Nomen + にたいして","Kurzform + の + にたいして","Nomen／な-Adjektiv + な + の + にたいして","Nomen + にたいする + Nomen"],examples:[{jp:"お客[きゃく]さんに対[たい]して、失礼[しつれい]なことを言[い]ってはいけません。",de:"Kunden gegenüber darf man nichts Unhöfliches sagen.",en:"You must not say rude things to customers."},{jp:"兄[あに]が静[しず]かなのに対[たい]して、弟[おとうと]はよく話[はな]します。",de:"Während der ältere Bruder ruhig ist, redet der jüngere viel.",en:"Whereas the older brother is quiet, the younger one talks a lot."}],matches:[],tags:["gegensatz","bezug"]},
  {id:"g-n3-ni-kurabete",type:"grammar",source:"JLPT N3",level:"N3",title:"〜に比べて – im Vergleich zu",jp:"〜に比[くら]べて",summary:"Nennt den Maßstab, an dem etwas gemessen wird. Es steht より nahe, ist aber etwas förmlicher, außerdem nicht auf „mehr/weniger“-Sätze beschränkt. にくらべると („wenn man es vergleicht“) wird genauso verwendet.",structure:["Nomen + にくらべて／にくらべると","Kurzform + の + にくらべて"],examples:[{jp:"去年[きょねん]に比[くら]べて、今年[ことし]は雨[あめ]が多[おお]いです。",de:"Im Vergleich zum letzten Jahr regnet es dieses Jahr viel.",en:"Compared to last year, there is a lot of rain this year."},{jp:"東京[とうきょう]に比[くら]べると、私[わたし]の町[まち]は物価[ぶっか]が安[やす]いです。",de:"Verglichen mit Tōkyō sind die Preise in meiner Stadt niedrig.",en:"Compared with Tokyo, prices in my town are low."}],matches:[],tags:["vergleich"]},
  {id:"g-n3-ni-tsurete",type:"grammar",source:"JLPT N3",level:"N3",title:"〜につれて – je mehr … desto, im Zuge von",jp:"〜につれて",summary:"Während sich A allmählich verändert, verändert sich B mit. In beiden Satzteilen stehen Wörter der Veränderung (なる, ふえる, ちかづく …). B ist eine natürliche Entwicklung, keine Absicht oder Bitte.",structure:["Wörterbuchform + につれて","Nomen + につれて"],examples:[{jp:"年[とし]を取[と]るにつれて、体力[たいりょく]がなくなってきました。",de:"Je älter ich werde, desto mehr lässt meine Kraft nach.",en:"As I have grown older, I have been losing my strength."},{jp:"試験[しけん]の日[ひ]が近[ちか]づくにつれて、不安[ふあん]になってきました。",de:"Je näher der Prüfungstag rückte, desto unruhiger wurde ich.",en:"As the day of the exam came closer, I grew more and more anxious."}],matches:[],tags:["veränderung","verhältnis"]},
  {id:"g-n3-to-tomo-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜と共に – zusammen mit; zugleich mit",jp:"〜と共[とも]に",summary:"Ein schriftsprachlicher Ausdruck, drei Verwendungen: „zusammen mit“ einer Person (wie といっしょに), „gleichzeitig mit“ einem Ereignis, sowie „wenn sich A ändert, ändert sich auch B“ (wie につれて).",structure:["Nomen + とともに","Wörterbuchform + とともに"],examples:[{jp:"家族[かぞく]と共[とも]に、新[あたら]しい町[まち]で生活[せいかつ]を始[はじ]めました。",de:"Zusammen mit meiner Familie habe ich in einer neuen Stadt ein neues Leben begonnen.",en:"Together with my family, I started a new life in a new town."},{jp:"時代[じだい]と共[とも]に、言葉[ことば]も変[か]わっていきます。",de:"Mit der Zeit verändert sich auch die Sprache.",en:"Language changes along with the times."}],matches:[],tags:["veränderung","schriftsprache"]},
  {id:"g-n3-ni-kakete",type:"grammar",source:"JLPT N3",level:"N3",title:"〜から〜にかけて – von … bis etwa, über … hinweg",jp:"〜から〜にかけて",summary:"Gibt einen ungefähren zeitlichen oder räumlichen Bereich an, in dem etwas andauert oder hier wie dort auftritt. Anders als bei から〜まで sind Anfang sowie Ende nicht genau. Typisch für Wetterberichte und Nachrichten.",structure:["Nomen + から + Nomen + にかけて"],examples:[{jp:"今夜[こんや]から明日[あした]の朝[あさ]にかけて、大雨[おおあめ]が降[ふ]るでしょう。",de:"Von heute Nacht bis morgen früh ist mit starkem Regen zu rechnen.",en:"Heavy rain is expected from tonight through tomorrow morning."},{jp:"六月[ろくがつ]から七月[しちがつ]にかけて、雨[あめ]の日[ひ]が多[おお]くなります。",de:"Von Juni bis in den Juli hinein gibt es mehr Regentage.",en:"From June into July there are more rainy days."}],matches:[],tags:["bereich","zeit"]},
  {id:"g-n3-wo-chuushin-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"〜を中心に – mit … im Mittelpunkt, vor allem",jp:"〜を中心[ちゅうしん]に",summary:"Nennt den Mittelpunkt eines Ortes, einer Gruppe, einer Tätigkeit oder eines Bereichs: Etwas liegt darum herum oder betrifft vor allem diesen Punkt. をちゅうしんにして und をちゅうしんとして sind gleichbedeutend; vor einem Nomen wird daraus をちゅうしんとした.",structure:["Nomen + をちゅうしんに(して)","Nomen + をちゅうしんとして","Nomen + をちゅうしんとした + Nomen"],examples:[{jp:"この歌手[かしゅ]は若[わか]い人[ひと]を中心[ちゅうしん]に人気[にんき]があります。",de:"Dieser Sänger ist vor allem bei jungen Leuten beliebt.",en:"This singer is popular mainly with young people."},{jp:"駅[えき]を中心[ちゅうしん]に、たくさんの店[みせ]が並[なら]んでいます。",de:"Rund um den Bahnhof reihen sich viele Geschäfte aneinander.",en:"Lots of shops are lined up around the station."}],matches:[],tags:["schwerpunkt"]},
  {id:"g-n3-gachi",type:"grammar",source:"JLPT N3",level:"N3",title:"〜がち – neigen zu, häufig passieren",jp:"〜がち",summary:"Sagt, dass etwas leicht oder oft passiert – fast immer etwas Unerwünschtes. Es verhält sich wie ein な-Adjektiv oder Nomen (がちだ, がちな, がちの). Nach Nomen steht es nur in wenigen festen Wörtern wie びょうきがち oder くもりがち.",structure:["Verbstamm (ます-Stamm) + がち","Nomen + がち"],examples:[{jp:"彼[かれ]は最近[さいきん]、授業[じゅぎょう]を休[やす]みがちです。",de:"In letzter Zeit fehlt er öfter im Unterricht.",en:"Lately he tends to miss classes."},{jp:"雨[あめ]の日[ひ]はバスが遅[おく]れがちです。",de:"An Regentagen haben die Busse häufig Verspätung.",en:"On rainy days the buses tend to be late."}],matches:[],tags:["nachsilbe","tendenz"]},
  {id:"g-n3-gimi",type:"grammar",source:"JLPT N3",level:"N3",title:"〜気味 – ein bisschen, leicht, ein Anflug von",jp:"〜ぎみ",summary:"Sagt, dass sich ein Zustand leicht bemerkbar macht, meist ein unangenehmer: „ich fühle mich ein bisschen …“. がち sagt, wie oft etwas vorkommt; ぎみ beschreibt, wie es im Moment aussieht oder sich anfühlt. Es steht nur bei bestimmten Wörtern (かぜぎみ, つかれぎみ, ふとりぎみ, おくれぎみ).",structure:["Nomen + ぎみ","Verbstamm (ます-Stamm) + ぎみ"],examples:[{jp:"今日[きょう]は風邪[かぜ]ぎみなので、早[はや]く帰[かえ]ります。",de:"Ich bin heute etwas erkältet, deshalb gehe ich früh nach Hause.",en:"I have a touch of a cold today, so I will go home early."},{jp:"最近[さいきん]、少[すこ]し太[ふと]りぎみです。",de:"In letzter Zeit habe ich ein bisschen zugenommen.",en:"Lately I have been putting on a little weight."}],matches:[],tags:["nachsilbe","tendenz"]},
  {id:"g-n3-ppoi",type:"grammar",source:"JLPT N3",level:"N3",title:"〜っぽい – -lich, -haft, wirkt wie; tut leicht",jp:"〜っぽい",summary:"Bildet ein い-Adjektiv: Nach einem Nomen oder Adjektiv heißt es „wirkt wie, hat etwas von“ (こどもっぽい, やすっぽい), nach einem Verbstamm „tut etwas leicht und oft“ (わすれっぽい, おこりっぽい). Es ist umgangssprachlich und oft leicht abwertend.",structure:["Nomen + っぽい","Verbstamm (ます-Stamm) + っぽい","い-Adjektiv ohne い + っぽい"],examples:[{jp:"兄[あに]はもう大人[おとな]なのに、子[こ]どもっぽいところがあります。",de:"Mein älterer Bruder ist schon erwachsen, hat aber etwas Kindisches an sich.",en:"My older brother is already an adult, but there is something childish about him."},{jp:"年[とし]を取[と]って、忘[わす]れっぽくなりました。",de:"Mit dem Alter bin ich vergesslich geworden.",en:"As I have got older, I have become forgetful."}],matches:[],tags:["nachsilbe","umgangssprache"]},
  {id:"g-n3-darake",type:"grammar",source:"JLPT N3",level:"N3",title:"〜だらけ – voller, über und über mit",jp:"〜だらけ",summary:"Sagt, dass etwas voll von etwas Unangenehmem oder damit bedeckt ist: Fehler, Müll, Schlamm, Schulden. Bei neutralen oder schönen Dingen verwendet man stattdessen いっぱい.",structure:["Nomen + だらけ","Nomen + だらけの + Nomen"],examples:[{jp:"弟[おとうと]の部屋[へや]はごみだらけです。",de:"Das Zimmer meines jüngeren Bruders ist voller Müll.",en:"My younger brother's room is full of rubbish."},{jp:"この作文[さくぶん]は間違[まちが]いだらけだ。",de:"Dieser Aufsatz wimmelt von Fehlern.",en:"This essay is full of mistakes."}],matches:[],tags:["nachsilbe"]},
  {id:"g-n3-gatai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜がたい – schwer zu, kaum zu",jp:"〜がたい",summary:"Sagt, dass man etwas kaum über sich bringt, so sehr man es auch versucht: Es ist gefühlsmäßig oder gedanklich schwer. Schriftsprache, nur bei wenigen Verben wie しんじる, わすれる, ゆるす, りかいする. Für Dinge, die körperlich oder technisch schwierig sind, nimmt man にくい oder できない.",structure:["Verbstamm (ます-Stamm) + がたい"],examples:[{jp:"彼[かれ]が会社[かいしゃ]をやめたとは信[しん]じがたい。",de:"Es ist kaum zu glauben, dass er in der Firma aufgehört hat.",en:"It is hard to believe that he has quit the company."},{jp:"日本[にほん]での一年[いちねん]は忘[わす]れがたい思[おも]い出[で]です。",de:"Das eine Jahr in Japan ist eine unvergessliche Erinnerung.",en:"My year in Japan is an unforgettable memory."}],matches:[],tags:["nachsilbe","schwierigkeit","förmlich"]},
  {id:"g-n3-kake",type:"grammar",source:"JLPT N3",level:"N3",title:"〜かけ／〜かける – halb fertig, mitten in",jp:"〜かけ／〜かける",summary:"Sagt, dass eine Handlung angefangen, aber nicht zu Ende gebracht wurde: ein halb gelesenes Buch, ein angebissener Apfel. Als Verb heißt 〜かける auch „im Begriff sein, etwas zu tun; beinahe tun“.",structure:["Verbstamm (ます-Stamm) + かけの + Nomen","Verbstamm (ます-Stamm) + かけだ","Verbstamm (ます-Stamm) + かける"],examples:[{jp:"机[つくえ]の上[うえ]に飲[の]みかけのコーヒーがあります。",de:"Auf dem Schreibtisch steht ein halb ausgetrunkener Kaffee.",en:"There is a half-finished cup of coffee on the desk."},{jp:"彼[かれ]は何[なに]か言[い]いかけて、やめました。",de:"Er setzte an, etwas zu sagen, ließ es dann aber.",en:"He started to say something and then stopped."}],matches:[],tags:["nachsilbe","unvollendet"]},
  {id:"g-n3-kiri",type:"grammar",source:"JLPT N3",level:"N3",title:"〜きり – nur; seitdem (nichts mehr)",jp:"〜きり",summary:"Nach einem Nomen oder einer Zahl betont きり „nur, bloß“ (ふたりきり, いちどきり). Nach der た-Form heißt es, dass etwas einmal geschehen ist, seitdem aber nichts mehr; meist folgt eine Verneinung. In der Umgangssprache wird es zu っきり.",structure:["Nomen／Zahl + きり","Kurzform der Vergangenheit (た-Form) + きり + Verneinung"],examples:[{jp:"二人[ふたり]きりで話[はな]したいことがあります。",de:"Es gibt etwas, das ich gern unter vier Augen besprechen würde.",en:"There is something I would like to talk about, just the two of us."},{jp:"彼[かれ]とは去年[きょねん]会[あ]ったきり、連絡[れんらく]がありません。",de:"Ich habe ihn letztes Jahr getroffen, seitdem habe ich nichts mehr von ihm gehört.",en:"I met him last year and have not heard from him since."}],matches:[],tags:["partikel","einschränkung"]},
  {id:"g-n3-kiru",type:"grammar",source:"JLPT N3",level:"N3",title:"〜切る – ganz, vollständig, bis zum Ende tun",jp:"〜きる",summary:"Verbstamm + きる sagt, dass eine Handlung bis zum Ende durchgeführt oder etwas restlos aufgebraucht wird (よみきる, つかいきる). Bei Verben für Gefühle oder Zustände heißt es „völlig, ganz und gar“ (つかれきる, こまりきる).",structure:["Verbstamm (ます-Stamm) + きる","よむ → よみきる"],examples:[{jp:"この本[ほん]は一日[いちにち]で読[よ]み切[き]りました。",de:"Ich habe dieses Buch an einem Tag ganz durchgelesen.",en:"I read this book from cover to cover in one day."},{jp:"一日中[いちにちじゅう]歩[ある]いて、疲[つか]れ切[き]っています。",de:"Ich bin den ganzen Tag gelaufen und völlig erschöpft.",en:"I walked all day and am completely exhausted."}],matches:[],tags:["zusammengesetztes verb","abschluss"]},
  {id:"g-n3-kirenai",type:"grammar",source:"JLPT N3",level:"N3",title:"〜切れない – nicht ganz schaffen, zu viel um zu",jp:"〜きれない",summary:"Die verneinte Potentialform von 〜きる: Etwas ist zu viel, um es vollständig zu tun. たべきれない heißt „nicht alles aufessen können“, かぞえきれない „unzählbar viele“.",structure:["Verbstamm (ます-Stamm) + きれない"],examples:[{jp:"料理[りょうり]が多[おお]すぎて、食[た]べ切[き]れません。",de:"Es ist zu viel Essen, ich schaffe nicht alles.",en:"There is too much food; I cannot eat it all."},{jp:"空[そら]には数[かぞ]え切[き]れないほどの星[ほし]が見[み]えました。",de:"Am Himmel waren unzählbar viele Sterne zu sehen.",en:"In the sky you could see more stars than you could count."}],matches:[],tags:["zusammengesetztes verb","potential"]},
  {id:"g-n3-komu",type:"grammar",source:"JLPT N3",level:"N3",title:"〜込む – hinein; tief, gründlich",jp:"〜こむ",summary:"Verbstamm + こむ hat zwei Bedeutungen: eine Bewegung in etwas hinein (かきこむ „eintragen“, とびこむ „hineinspringen“) oder etwas tief, gründlich oder lange tun (かんがえこむ „in Gedanken versinken“, おもいこむ „fest überzeugt sein“). Viele dieser Verbindungen sind feste Wörter, die man am besten einzeln lernt.",structure:["Verbstamm (ます-Stamm) + こむ","かく → かきこむ"],examples:[{jp:"旅行[りょこう]の前[まえ]に、かばんに荷物[にもつ]を詰[つ]め込[こ]みました。",de:"Vor der Reise habe ich meine Sachen in die Tasche gestopft.",en:"Before the trip I stuffed my things into the bag."},{jp:"彼[かれ]は何[なに]か考[かんが]え込[こ]んでいるようです。",de:"Er scheint über irgendetwas tief nachzugrübeln.",en:"He seems to be deep in thought about something."}],matches:[],tags:["zusammengesetztes verb"]},
  {id:"g-n3-ageru-complete",type:"grammar",source:"JLPT N3",level:"N3",title:"〜上げる／〜上がる – fertigstellen, fertig werden",jp:"〜あげる／〜あがる",summary:"Verbstamm + あげる sagt, dass jemand etwas fertigstellt (かきあげる, つくりあげる); 〜あがる ist das intransitive Gegenstück: Etwas ist fertig geworden (できあがる, やきあがる). Das ist nicht das あげる für „geben“ oder für einen Gefallen (〜てあげる), das an die て-Form tritt.",structure:["Verbstamm (ます-Stamm) + あげる (transitiv)","Verbstamm (ます-Stamm) + あがる (intransitiv)"],examples:[{jp:"一週間[いっしゅうかん]でレポートを書[か]き上[あ]げました。",de:"Ich habe den Bericht in einer Woche fertig geschrieben.",en:"I finished writing the report in one week."},{jp:"パンが焼[や]き上[あ]がりました。",de:"Das Brot ist fertig gebacken.",en:"The bread is baked and ready."}],matches:[],tags:["zusammengesetztes verb","abschluss"]},
  {id:"g-n3-au",type:"grammar",source:"JLPT N3",level:"N3",title:"〜合う – einander, gegenseitig, miteinander",jp:"〜あう",summary:"Verbstamm + あう sagt, dass zwei oder mehr Personen dasselbe miteinander oder füreinander tun: はなしあう „sich besprechen“, たすけあう „einander helfen“. Der Partner wird mit と markiert.",structure:["Verbstamm (ます-Stamm) + あう","はなす → はなしあう"],examples:[{jp:"困[こま]ったときは、助[たす]け合[あ]いましょう。",de:"Lasst uns einander helfen, wenn wir in Schwierigkeiten sind.",en:"Let's help each other when we are in trouble."},{jp:"その問題[もんだい]についてクラスで話[はな]し合[あ]いました。",de:"Wir haben in der Klasse über dieses Problem diskutiert.",en:"We discussed that problem in class."}],matches:[],tags:["zusammengesetztes verb","gegenseitig"]},
  {id:"g-n3-tate",type:"grammar",source:"JLPT N3",level:"N3",title:"〜たて – frisch, gerade erst",jp:"〜たて",summary:"Sagt, dass etwas gerade erst gemacht oder getan wurde, also noch frisch oder neu ist. Es steht nur bei bestimmten Verben (やく, たく, とる, ぬる, できる, ならう) – das Ergebnis verhält sich wie ein Nomen: たての + Nomen, たてだ.",structure:["Verbstamm (ます-Stamm) + たての + Nomen","Verbstamm (ます-Stamm) + たてだ"],examples:[{jp:"焼[や]きたてのパンはおいしいです。",de:"Frisch gebackenes Brot schmeckt gut.",en:"Freshly baked bread is delicious."},{jp:"このベンチはペンキを塗[ぬ]りたてですから、座[すわ]らないでください。",de:"Diese Bank ist frisch gestrichen, bitte setzen Sie sich nicht darauf.",en:"This bench has just been painted, so please do not sit on it."}],matches:[],tags:["nachsilbe","zeit"]},
  {id:"g-n3-ppanashi",type:"grammar",source:"JLPT N3",level:"N3",title:"〜っぱなし – einfach so lassen; ununterbrochen",jp:"〜っぱなし",summary:"Sagt, dass etwas in einem Zustand gelassen wird, obwohl man sich darum hätte kümmern sollen (Licht an, Tür offen), oder dass eine Handlung ohne Pause andauert (たちっぱなし). Anders als das neutrale まま klingt es nach Kritik oder Klage.",structure:["Verbstamm (ます-Stamm) + っぱなし","あける → あけっぱなし"],examples:[{jp:"電気[でんき]をつけっぱなしで寝[ね]てしまいました。",de:"Ich bin bei eingeschaltetem Licht eingeschlafen.",en:"I fell asleep with the light left on."},{jp:"今日[きょう]は一日中[いちにちじゅう]立[た]ちっぱなしで、足[あし]が痛[いた]いです。",de:"Ich habe heute den ganzen Tag gestanden, mir tun die Beine weh.",en:"I was on my feet all day today and my legs hurt."}],matches:[],tags:["nachsilbe","zustand"]},
  {id:"g-n3-muki",type:"grammar",source:"JLPT N3",level:"N3",title:"〜向き – geeignet für; ausgerichtet nach",jp:"〜むき",summary:"Nomen + むき sagt, dass etwas zu einer bestimmten Gruppe oder einem Zweck passt. 〜むけ dagegen heißt, dass es absichtlich für diese Gruppe gemacht wurde. Nach einer Himmelsrichtung heißt むき „ausgerichtet nach“: みなみむき.",structure:["Nomen + むきだ","Nomen + むきの + Nomen","Nomen + むきに"],examples:[{jp:"この料理[りょうり]は辛[から]くないので、子[こ]ども向[む]きです。",de:"Dieses Gericht ist nicht scharf, deshalb ist es für Kinder geeignet.",en:"This dish is not spicy, so it is suitable for children."},{jp:"南向[みなみむ]きの部屋[へや]は明[あか]るいです。",de:"Zimmer nach Süden sind hell.",en:"Rooms facing south are bright."}],matches:[],tags:["nachsilbe","eignung"]},
  {id:"g-n3-muke",type:"grammar",source:"JLPT N3",level:"N3",title:"〜向け – gedacht für, gerichtet an",jp:"〜むけ",summary:"Nomen + むけ sagt, dass etwas gezielt für eine bestimmte Gruppe entworfen oder hergestellt wurde. 〜むき sagt nur, dass es zu dieser Gruppe passt.",structure:["Nomen + むけだ","Nomen + むけの + Nomen","Nomen + むけに"],examples:[{jp:"これは外国人[がいこくじん]向[む]けの日本語[にほんご]の本[ほん]です。",de:"Das ist ein Japanischbuch für Ausländer.",en:"This is a Japanese book intended for foreigners."},{jp:"この番組[ばんぐみ]は子[こ]ども向[む]けに作[つく]られています。",de:"Diese Sendung wird für Kinder gemacht.",en:"This programme is made for children."}],matches:[],tags:["nachsilbe","zielgruppe"]},
  {id:"g-n3-chuu",type:"grammar",source:"JLPT N3",level:"N3",title:"〜中 – gerade bei, während; den ganzen … über",jp:"〜ちゅう／〜じゅう",summary:"ちゅう gelesen heißt es, dass etwas gerade im Gang ist (かいぎちゅう, でんわちゅう); zusammen mit に nennt es eine Frist „innerhalb von, im Laufe von“ (こんしゅうちゅうに). じゅう gelesen heißt es „den ganzen … über, überall in“ (いちにちじゅう, せかいじゅう). Welche Lesung gilt, ist bei jedem Wort festgelegt.",structure:["Nomen (Tätigkeit) + ちゅう","Nomen (Zeitraum) + ちゅうに","Nomen (Zeit／Ort) + じゅう"],examples:[{jp:"田中[たなか]さんは今[いま]、会議中[かいぎちゅう]です。",de:"Herr Tanaka ist gerade in einer Besprechung.",en:"Mr Tanaka is in a meeting right now."},{jp:"昨日[きのう]は一日中[いちにちじゅう]雨[あめ]が降[ふ]っていました。",de:"Gestern hat es den ganzen Tag geregnet.",en:"Yesterday it rained all day long."}],matches:[],tags:["nachsilbe","zeit"]},
  {id:"g-n3-teki",type:"grammar",source:"JLPT N3",level:"N3",title:"〜的 – -isch, -lich, -mäßig",jp:"〜てき",summary:"Macht aus einem Nomen (meist einem Kanji-Kompositum) ein な-Adjektiv: でんとう „Tradition“ → でんとうてき „traditionell“. Mit な steht es vor einem Nomen, mit に wird es zum Adverb.",structure:["Nomen + てき + な + Nomen","Nomen + てき + に + Verb／Adjektiv","Nomen + てきだ"],examples:[{jp:"京都[きょうと]には伝統的[でんとうてき]な建物[たてもの]がたくさんあります。",de:"In Kyōto gibt es viele traditionelle Gebäude.",en:"There are many traditional buildings in Kyoto."},{jp:"もっと具体的[ぐたいてき]に説明[せつめい]してください。",de:"Bitte erklären Sie es konkreter.",en:"Please explain it more concretely."}],matches:[],tags:["nachsilbe","adjektiv"]},
  {id:"g-n3-zutsu",type:"grammar",source:"JLPT N3",level:"N3",title:"〜ずつ – je, jeweils, nach und nach",jp:"〜ずつ",summary:"Nach einer Zahl oder Menge heißt ずつ, dass jeder gleich viel bekommt oder jedes Mal dieselbe Menge an der Reihe ist: ひとつずつ „je eins, eins nach dem anderen“, すこしずつ „nach und nach“.",structure:["Zahl／Zählwort + ずつ","すこし + ずつ"],examples:[{jp:"一人[ひとり]ずつ名前[なまえ]を言[い]ってください。",de:"Bitte sagen Sie einer nach dem anderen Ihren Namen.",en:"Please say your names one at a time."},{jp:"日本語[にほんご]が少[すこ]しずつ上手[じょうず]になってきました。",de:"Mein Japanisch ist nach und nach besser geworden.",en:"My Japanese has been getting better little by little."}],matches:[],tags:["partikel","menge"]},
  {id:"g-n3-sae",type:"grammar",source:"JLPT N3",level:"N3",title:"〜さえ – sogar, nicht einmal",jp:"〜さえ",summary:"Greift ein extremes Beispiel heraus, um zu zeigen, dass alles andere erst recht gilt: „sogar …, nicht einmal …“. Es ist stärker und steifer als も. さえ ersetzt が und を; andere Partikeln bleiben stehen (にさえ), beim Subjekt steht oft でさえ.",structure:["Nomen + さえ","Nomen + Partikel + さえ","Nomen + でさえ"],examples:[{jp:"忙[いそが]しくて、昼[ひる]ご飯[はん]を食[た]べる時間[じかん]さえありません。",de:"Ich habe so viel zu tun, dass ich nicht einmal Zeit zum Mittagessen habe.",en:"I am so busy that I do not even have time to eat lunch."},{jp:"そんなことは子[こ]どもでさえ知[し]っています。",de:"So etwas weiß sogar ein Kind.",en:"Even a child knows that."}],matches:[],tags:["partikel","betonung"]},
  {id:"g-n3-koso",type:"grammar",source:"JLPT N3",level:"N3",title:"〜こそ – gerade, genau, eben",jp:"〜こそ",summary:"Betont das Wort davor sehr stark: „genau dieses, kein anderes“. Es ersetzt は, が und を. Nach から betont es einen Grund (〜からこそ „gerade weil“). Bekannt aus こちらこそ „ganz meinerseits“.",structure:["Nomen + こそ","Kurzform + から + こそ"],examples:[{jp:"こちらこそ、よろしくお願[ねが]いします。",de:"Ganz meinerseits, auf gute Zusammenarbeit.",en:"The pleasure is all mine; I look forward to working with you."},{jp:"今年[ことし]こそ試験[しけん]に合格[ごうかく]したいです。",de:"Dieses Jahr will ich die Prüfung aber wirklich bestehen.",en:"This year, for sure, I want to pass the exam."}],matches:[],tags:["partikel","betonung"]},
  {id:"g-n3-nanka",type:"grammar",source:"JLPT N3",level:"N3",title:"〜なんか／〜なんて – so etwas wie; und dergleichen",jp:"〜なんか／〜なんて",summary:"Umgangssprachliche Varianten von など. Sie nennen ein Beispiel („so etwas wie …“), spielen etwas herunter oder zeigen Abneigung, oder man macht sich damit selbst bescheiden klein. なんて kann auch nach einem ganzen Satz stehen – dann drückt es Staunen oder Unglauben aus: „dass …!“.",structure:["Nomen + なんか","Nomen + なんて","Kurzform + なんて"],examples:[{jp:"お酒[さけ]なんか飲[の]みたくないです。",de:"So etwas wie Alkohol will ich nicht trinken.",en:"I do not want to drink alcohol or anything like that."},{jp:"彼[かれ]が試験[しけん]に落[お]ちるなんて、信[しん]じられません。",de:"Dass ausgerechnet er durch die Prüfung fällt, kann ich nicht glauben.",en:"I cannot believe that he, of all people, failed the exam."}],matches:[],tags:["partikel","umgangssprache"]},
  {id:"g-n3-sate",type:"grammar",source:"JLPT N3",level:"N3",title:"さて – nun, also dann",jp:"さて",summary:"Steht am Satzanfang, wenn man zum nächsten Thema oder zum nächsten Schritt übergeht. Typisch in Vorträgen, im Unterricht, in Briefen oder wenn man sich anschickt, etwas zu tun.",structure:["さて、+ Satz"],examples:[{jp:"さて、次[つぎ]の問題[もんだい]に進[すす]みましょう。",de:"Nun, gehen wir zur nächsten Aufgabe weiter.",en:"Well then, let's move on to the next question."},{jp:"さて、そろそろ帰[かえ]りましょうか。",de:"So, wollen wir uns langsam auf den Heimweg machen?",en:"Well, shall we head home soon?"}],matches:[],tags:["konjunktion"]},
  {id:"g-n3-sude-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"すでに – bereits, schon",jp:"すでに",summary:"Heißt „schon“ wie もう, klingt aber förmlicher; häufig in geschriebenen Texten, Nachrichten oder im Geschäftsleben. Es steht oft bei 〜ている oder 〜ていた, manchmal schwingt mit, dass es zu spät ist.",structure:["すでに + Verb (oft 〜ている／〜ていた)"],examples:[{jp:"駅[えき]に着[つ]いたとき、電車[でんしゃ]はすでに出[で]ていました。",de:"Als ich am Bahnhof ankam, war der Zug bereits abgefahren.",en:"When I got to the station, the train had already left."},{jp:"チケットはすでに売[う]り切[き]れています。",de:"Die Karten sind bereits ausverkauft.",en:"The tickets are already sold out."}],matches:[],tags:["adverb","förmlich"]},
  {id:"g-n3-sunawachi",type:"grammar",source:"JLPT N3",level:"N3",title:"すなわち – das heißt, nämlich",jp:"すなわち",summary:"Sagt dasselbe noch einmal in anderen, genaueren Worten: A, すなわち B. Steife Schriftsprache in Erklärungen, Reden oder Lehrbüchern; im Gespräch sagt man つまり.",structure:["A、すなわち B"],examples:[{jp:"試験[しけん]は来週[らいしゅう]の月曜日[げつようび]、すなわち十日[とおか]に行[おこな]われます。",de:"Die Prüfung findet nächsten Montag statt, das heißt am Zehnten.",en:"The exam will be held next Monday, that is, on the tenth."}],matches:[],tags:["konjunktion","förmlich"]},
  {id:"g-n3-tsumari",type:"grammar",source:"JLPT N3",level:"N3",title:"つまり – mit anderen Worten, kurz gesagt",jp:"つまり",summary:"Fasst das eben Gesagte zusammen oder drückt es anders aus: „also, das heißt, es läuft darauf hinaus, dass …“. Man fragt damit auch nach, wie der andere etwas gemeint hat. Der Satz endet oft auf ということだ oder わけだ.",structure:["A、つまり B","つまり、+ Satz (+ ということだ)"],examples:[{jp:"彼女[かのじょ]は父[ちち]の妹[いもうと]、つまり私[わたし]のおばです。",de:"Sie ist die jüngere Schwester meines Vaters, also meine Tante.",en:"She is my father's younger sister, in other words my aunt."},{jp:"つまり、行[い]きたくないということですね。",de:"Sie wollen also nicht hingehen, verstehe ich das richtig?",en:"In other words, you do not want to go, right?"}],matches:[],tags:["konjunktion"]},
  {id:"g-n3-tatoeba",type:"grammar",source:"JLPT N3",level:"N3",title:"例えば – zum Beispiel",jp:"たとえば",summary:"Leitet ein Beispiel für das eben Gesagte ein. Es steht am Satzanfang oder direkt vor dem Beispiel, oft zusammen mit など oder とか.",structure:["たとえば、+ Satz","A、たとえば B や C"],examples:[{jp:"私[わたし]は日本[にほん]の料理[りょうり]、たとえばすしや天[てん]ぷらが好[す]きです。",de:"Ich mag japanisches Essen, zum Beispiel Sushi oder Tempura.",en:"I like Japanese food, for example sushi and tempura."},{jp:"たとえば、週末[しゅうまつ]に一緒[いっしょ]に映画[えいが]を見[み]るのはどうですか。",de:"Wie wäre es zum Beispiel, wenn wir am Wochenende zusammen einen Film ansehen?",en:"How about, for example, watching a film together at the weekend?"}],matches:[],tags:["konjunktion","beispiel"]},
  {id:"g-n3-tokoroga",type:"grammar",source:"JLPT N3",level:"N3",title:"ところが – doch, aber (wider Erwarten)",jp:"ところが",summary:"Leitet einen Satz ein, der berichtet, dass etwas anders gekommen ist als erwartet. Danach steht eine Tatsache, die den Sprecher überrascht hat, nie eine Absicht, Bitte oder Meinung – dafür nimmt man しかし oder でも.",structure:["Satz。ところが、+ unerwartete Tatsache"],examples:[{jp:"天気[てんき]予報[よほう]では晴[は]れると言[い]っていました。ところが、午後[ごご]から雨[あめ]が降[ふ]り出[だ]しました。",de:"Im Wetterbericht hieß es, es werde sonnig. Doch am Nachmittag fing es an zu regnen.",en:"The weather forecast said it would be sunny. However, it started to rain in the afternoon."}],matches:[],tags:["konjunktion","gegensatz"]},
  {id:"g-n3-tokorode",type:"grammar",source:"JLPT N3",level:"N3",title:"ところで – übrigens",jp:"ところで",summary:"Steht am Satzanfang, wenn man das Thema wechselt, zu etwas, das nichts mit dem Vorigen zu tun hat. Nicht verwechseln: ところが drückt einen Gegensatz zum Vorigen aus.",structure:["ところで、+ neues Thema"],examples:[{jp:"ところで、週末[しゅうまつ]は何[なに]をしましたか。",de:"Übrigens, was haben Sie am Wochenende gemacht?",en:"By the way, what did you do at the weekend?"},{jp:"もう十二時[じゅうにじ]ですね。ところで、お昼[ひる]はどうしますか。",de:"Es ist ja schon zwölf Uhr. Übrigens, was machen wir zu Mittag?",en:"It is twelve o'clock already. By the way, what shall we do about lunch?"}],matches:[],tags:["konjunktion","thema"]},
  {id:"g-n3-nazenara",type:"grammar",source:"JLPT N3",level:"N3",title:"なぜなら – denn, der Grund ist",jp:"なぜなら〜からだ",summary:"Zuerst kommt eine Aussage, dann nennt ein neuer Satz, der mit なぜなら beginnt, den Grund; dieser Satz endet auf からだ／からです. Es klingt logisch, eher steif – passend für Aufsätze oder Vorträge. Im Alltag sagt man だって oder einfach 〜から.",structure:["Aussage。なぜなら(ば)、+ Grund + からだ"],examples:[{jp:"私[わたし]は夏[なつ]が好[す]きです。なぜなら、海[うみ]で泳[およ]げるからです。",de:"Ich mag den Sommer. Denn dann kann ich im Meer schwimmen.",en:"I like summer. The reason is that I can swim in the sea."},{jp:"今日[きょう]は出[で]かけません。なぜなら、明日[あした]試験[しけん]があるからです。",de:"Heute gehe ich nicht aus, denn morgen habe ich eine Prüfung.",en:"I am not going out today, because I have an exam tomorrow."}],matches:[],tags:["konjunktion","grund","förmlich"]},
  {id:"g-n3-tsui",type:"grammar",source:"JLPT N3",level:"N3",title:"つい – unwillkürlich, ohne es zu wollen",jp:"つい",summary:"Sagt, dass man etwas tut, obwohl man es nicht vorhatte – aus Gewohnheit oder weil man nicht widerstehen konnte. Sehr oft zusammen mit 〜てしまう. Vor Zeit- oder Entfernungsangaben heißt es „erst, gerade eben“ (ついさっき „gerade vorhin“).",structure:["つい + Verb (oft 〜てしまう)"],examples:[{jp:"甘[あま]い物[もの]があると、つい食[た]べすぎてしまいます。",de:"Wenn Süßes da ist, esse ich unwillkürlich zu viel davon.",en:"When there are sweets around, I end up eating too many without meaning to."},{jp:"話[はなし]が楽[たの]しくて、つい時間[じかん]を忘[わす]れてしまいました。",de:"Das Gespräch war so nett, dass ich ganz die Zeit vergessen habe.",en:"The conversation was so much fun that I lost track of time."}],matches:[],tags:["adverb","unabsichtlich"]},
  {id:"g-n3-tsui-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"ついに – endlich, schließlich, am Ende",jp:"ついに",summary:"Sagt, dass nach langer Zeit oder viel Mühe ein Endergebnis erreicht ist. Das Ergebnis kann gut oder schlecht sein; bei einer Verneinung heißt es „am Ende doch nicht“. やっと dagegen steht nur bei gutem Ausgang, es drückt Erleichterung aus.",structure:["ついに + Verb"],examples:[{jp:"三年[さんねん]かかって、ついに家[いえ]が完成[かんせい]しました。",de:"Nach drei Jahren ist das Haus endlich fertig geworden.",en:"After three years, the house was finally completed."},{jp:"一時間[いちじかん]待[ま]ちましたが、彼[かれ]はついに来[き]ませんでした。",de:"Ich habe eine Stunde gewartet, aber er ist am Ende nicht gekommen.",en:"I waited for an hour, but in the end he never came."}],matches:[],tags:["adverb","zeit"]},
  {id:"g-n3-futo",type:"grammar",source:"JLPT N3",level:"N3",title:"ふと – plötzlich, zufällig, ohne besonderen Grund",jp:"ふと",summary:"Sagt, dass etwas beiläufig geschieht, ohne Grund oder Absicht: Man schaut zufällig auf, ein Gedanke kommt einem plötzlich in den Sinn. Typisch bei みる, おもう, おもいだす, きがつく.",structure:["ふと + Verb"],examples:[{jp:"ふと窓[まど]の外[そと]を見[み]ると、雪[ゆき]が降[ふ]っていました。",de:"Als ich zufällig aus dem Fenster schaute, schneite es.",en:"When I happened to look out of the window, it was snowing."},{jp:"歩[ある]いているとき、ふと昔[むかし]の友[とも]だちを思[おも]い出[だ]しました。",de:"Beim Gehen fiel mir plötzlich ein alter Freund ein.",en:"While I was walking, an old friend suddenly came to my mind."}],matches:[],tags:["adverb","unabsichtlich"]},
  {id:"g-n3-masaka",type:"grammar",source:"JLPT N3",level:"N3",title:"まさか – doch wohl nicht, niemals gedacht",jp:"まさか",summary:"Drückt Unglauben aus: Etwas ist so unwahrscheinlich, dass man es sich nicht vorstellen kann oder konnte. Der Satz endet meist verneint, etwa auf 〜とはおもわなかった, 〜ないだろう oder 〜はずがない. Allein heißt まさか！ „Das gibt's doch nicht!“.",structure:["まさか + Teilsatz + とはおもわなかった","まさか + Teilsatz + ないだろう","まさか！"],examples:[{jp:"まさか自分[じぶん]が一位[いちい]になるとは思[おも]いませんでした。",de:"Ich hätte nie gedacht, dass ich Erster werde.",en:"I never thought that I would come first."},{jp:"あの二人[ふたり]が結婚[けっこん]するんですか。まさか！",de:"Die beiden heiraten? Das gibt's doch nicht!",en:"Those two are getting married? No way!"}],matches:[],tags:["adverb","überraschung"]},
  {id:"g-n3-mushiro",type:"grammar",source:"JLPT N3",level:"N3",title:"むしろ – eher, vielmehr, lieber",jp:"むしろ",summary:"Vergleicht zwei Dinge; das zweite trifft besser zu oder ist vorzuziehen, oft anders, als man erwarten würde. Typisch nach 〜より oder 〜というより.",structure:["A より(も)、むしろ B","A というより、むしろ B"],examples:[{jp:"私[わたし]は肉[にく]より、むしろ魚[さかな]のほうが好[す]きです。",de:"Ich mag eher Fisch als Fleisch.",en:"I like fish rather than meat."},{jp:"電車[でんしゃ]で行[い]くより、むしろ歩[ある]いたほうが早[はや]いです。",de:"Zu Fuß ist man eher schneller als mit der Bahn.",en:"If anything, walking is faster than going by train."}],matches:[],tags:["adverb","vergleich"]},
  {id:"g-n3-marude",type:"grammar",source:"JLPT N3",level:"N3",title:"まるで – ganz wie, als ob",jp:"まるで〜ようだ",summary:"Verstärkt einen Vergleich: „genau so, als ob …“, obwohl es in Wirklichkeit nicht so ist. Es steht zusammen mit ようだ oder dem lockereren みたいだ. Bei einer Verneinung heißt まるで „überhaupt nicht“ (まるでわからない).",structure:["まるで + Nomen + の + ようだ","まるで + Kurzform + ようだ","まるで + Nomen／Kurzform + みたいだ"],examples:[{jp:"今日[きょう]は暖[あたた]かくて、まるで春[はる]のようです。",de:"Heute ist es so warm, ganz wie im Frühling.",en:"It is so warm today, it is just like spring."},{jp:"彼女[かのじょ]はまるで日本人[にほんじん]みたいに日本語[にほんご]を話[はな]します。",de:"Sie spricht Japanisch, als wäre sie Japanerin.",en:"She speaks Japanese just like a Japanese person."}],matches:[],tags:["adverb","vergleich"]},
  {id:"g-n3-moshikashitara",type:"grammar",source:"JLPT N3",level:"N3",title:"もしかしたら – vielleicht, möglicherweise",jp:"もしかしたら〜かもしれない",summary:"Kündigt am Satzanfang an, dass das Folgende nur eine Möglichkeit ist; der Satz endet meist auf かもしれない. もしかすると bedeutet dasselbe, das lockere もしかして steht häufig in Fragen („kann es sein, dass …?“).",structure:["もしかしたら + Teilsatz + かもしれない","もしかして + Teilsatz + (の)？"],examples:[{jp:"もしかしたら、明日[あした]は行[い]けないかもしれません。",de:"Möglicherweise kann ich morgen nicht kommen.",en:"I might possibly not be able to go tomorrow."},{jp:"もしかしたら、かぎを家[いえ]に忘[わす]れたのかもしれません。",de:"Vielleicht habe ich meinen Schlüssel zu Hause vergessen.",en:"Perhaps I left my key at home."}],matches:[],tags:["adverb","vermutung"]},
  {id:"g-n3-nakanaka",type:"grammar",source:"JLPT N3",level:"N3",title:"なかなか – ziemlich, recht; (verneint) einfach nicht",jp:"なかなか／なかなか〜ない",summary:"Im bejahten Satz heißt なかなか „ziemlich, recht“, oft besser als erwartet; weil es wie ein Urteil klingt, vermeidet man es über Höhergestellte. Bei einem verneinten Verb heißt es, dass etwas nicht so leicht oder lange nicht eintritt, obwohl man es sich wünscht.",structure:["なかなか + Adjektiv","なかなか + verneintes Verb"],examples:[{jp:"この映画[えいが]はなかなかおもしろいですよ。",de:"Dieser Film ist ziemlich interessant.",en:"This film is quite interesting, you know."},{jp:"バスがなかなか来[き]ません。",de:"Der Bus kommt einfach nicht.",en:"The bus just will not come."}],matches:[],tags:["adverb","grad"]},
  {id:"g-n3-narubeku",type:"grammar",source:"JLPT N3",level:"N3",title:"なるべく – möglichst, wenn es geht",jp:"なるべく",summary:"Sagt, dass etwas so weit getan werden soll, wie es die Umstände erlauben. Häufig in Bitten oder bei Vorsätzen (〜てください, 〜ようにする). できるだけ bedeutet fast dasselbe, klingt aber etwas stärker: „so sehr man nur kann“.",structure:["なるべく + Adverb／Verb"],examples:[{jp:"なるべく早[はや]く返事[へんじ]をください。",de:"Bitte antworten Sie möglichst bald.",en:"Please reply as soon as possible."},{jp:"体[からだ]のために、なるべく野菜[やさい]を食[た]べるようにしています。",de:"Meiner Gesundheit zuliebe versuche ich, möglichst viel Gemüse zu essen.",en:"For the sake of my health, I try to eat vegetables as much as possible."}],matches:[],tags:["adverb","grad"]},
  {id:"g-n3-doushitemo",type:"grammar",source:"JLPT N3",level:"N3",title:"どうしても – unbedingt, um jeden Preis; beim besten Willen nicht",jp:"どうしても",summary:"Im bejahten Satz zeigt es einen starken Wunsch oder Zwang: „koste es, was es wolle“ (oft bei 〜たい oder 〜なければならない). Bei einer Verneinung, meist einer verneinten Potentialform, heißt es, dass etwas nicht klappt, so sehr man sich auch bemüht.",structure:["どうしても + 〜たい／〜なければならない","どうしても + Verneinung (Potential)"],examples:[{jp:"どうしてもあのコンサートに行[い]きたいです。",de:"Ich möchte unbedingt zu diesem Konzert gehen.",en:"I want to go to that concert no matter what."},{jp:"この漢字[かんじ]の読[よ]み方[かた]がどうしても思[おも]い出[だ]せません。",de:"Mir fällt beim besten Willen nicht ein, wie man dieses Kanji liest.",en:"I simply cannot remember how to read this kanji."}],matches:[],tags:["adverb","betonung"]},
  {id:"g-n3-totemo-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"とても〜ない – unmöglich, beim besten Willen nicht",jp:"とても〜ない",summary:"Bei einer Verneinung heißt とても nicht „sehr“, sondern „auf keinen Fall, unmöglich“. Es steht meist bei einer verneinten Potentialform oder bei Wörtern wie むりだ oder みえない: Wie man es auch dreht, es geht nicht.",structure:["とても + verneinte Potentialform","とても + むりだ／みえない"],examples:[{jp:"こんなにたくさんの料理[りょうり]は、一人[ひとり]ではとても食[た]べられません。",de:"So viel Essen kann ich allein unmöglich aufessen.",en:"I cannot possibly eat this much food on my own."},{jp:"彼[かれ]はとても五十歳[ごじゅっさい]には見[み]えません。",de:"Er sieht überhaupt nicht wie fünfzig aus.",en:"He does not look fifty at all."}],matches:[],tags:["adverb","verneinung"]},
  {id:"g-n3-betsu-ni-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"別に〜ない – nicht besonders, eigentlich nicht",jp:"べつに〜ない",summary:"Sagt, dass etwas nicht sonderlich zutrifft: „nicht besonders, nichts Bestimmtes“. Im lockeren Gespräch lässt die kurze Antwort べつに。 („Eigentlich nicht.“) die Verneinung weg; das kann kühl oder desinteressiert klingen.",structure:["べつに + Verneinung"],examples:[{jp:"今日[きょう]はべつに忙[いそが]しくないので、手伝[てつだ]えますよ。",de:"Ich habe heute nicht besonders viel zu tun, ich kann dir also helfen.",en:"I am not particularly busy today, so I can help you."},{jp:"べつに用事[ようじ]はありませんが、ちょっと電話[でんわ]してみました。",de:"Ich habe kein bestimmtes Anliegen, ich wollte nur mal kurz anrufen.",en:"I have nothing in particular to tell you; I just thought I would give you a call."}],matches:[],tags:["adverb","verneinung"]},
  {id:"g-n3-metta-ni-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"めったに〜ない – kaum jemals, selten",jp:"めったに〜ない",summary:"Sagt, dass etwas fast nie vorkommt. Es steht immer bei einer Verneinung, stärker als あまり〜ない. めったにない + Nomen oder 〜はめったにない heißt „sehr selten“.",structure:["めったに + verneintes Verb","Nomen + は + めったにない"],examples:[{jp:"父[ちち]はめったに怒[おこ]りません。",de:"Mein Vater wird fast nie wütend.",en:"My father hardly ever gets angry."},{jp:"こんなチャンスはめったにないですよ。",de:"So eine Chance gibt es nur ganz selten.",en:"A chance like this is very rare, you know."}],matches:[],tags:["adverb","häufigkeit","verneinung"]},
  {id:"g-n3-kesshite-nai",type:"grammar",source:"JLPT N3",level:"N3",title:"決して〜ない – niemals, auf keinen Fall",jp:"けっして〜ない",summary:"Verstärkt eine Verneinung: „niemals, unter keinen Umständen“. Es drückt einen festen Vorsatz, eine entschiedene Zurückweisung oder ein strenges Verbot (〜てはいけない) aus, förmlicher oder nachdrücklicher als ぜんぜん oder ぜったいに.",structure:["けっして + Verneinung","けっして + 〜てはいけない"],examples:[{jp:"このことは決[けっ]して忘[わす]れません。",de:"Das werde ich niemals vergessen.",en:"I will never forget this."},{jp:"決[けっ]して一人[ひとり]で川[かわ]に行[い]ってはいけません。",de:"Du darfst auf keinen Fall allein zum Fluss gehen.",en:"You must never go to the river alone."}],matches:[],tags:["adverb","verneinung","betonung"]},
  {id:"g-n3-ittai",type:"grammar",source:"JLPT N3",level:"N3",title:"一体 – was um alles in der Welt, wer bloß",jp:"いったい",summary:"Steht vor einem Fragewort; die Frage wird dadurch nachdrücklich: Der Sprecher ist ratlos, überrascht oder verärgert. Bei neutralen Auskunftsfragen verwendet man es nicht.",structure:["いったい + Fragewort (なに／だれ／どこ／どう／なぜ) … か"],examples:[{jp:"一体[いったい]何[なに]があったんですか。",de:"Was um alles in der Welt ist passiert?",en:"What on earth happened?"},{jp:"彼[かれ]は一体[いったい]どこへ行[い]ったのだろう。",de:"Wo mag er bloß hingegangen sein?",en:"Where in the world can he have gone?"}],matches:[],tags:["adverb","betonung","frage"]},
  {id:"g-n3-wazawaza",type:"grammar",source:"JLPT N3",level:"N3",title:"わざわざ – extra, eigens, sich die Mühe machen",jp:"わざわざ",summary:"Sagt, dass sich jemand eigens die Mühe macht, etwas zu tun, das nicht unbedingt nötig gewesen wäre. Man bedankt sich damit für die Mühe, wundert sich aber auch damit, warum sich jemand solche Umstände macht. Nicht verwechseln: わざと heißt „absichtlich“, in böser Absicht.",structure:["わざわざ + Verb"],examples:[{jp:"わざわざ駅[えき]まで迎[むか]えに来[き]てくれて、ありがとう。",de:"Danke, dass du extra bis zum Bahnhof gekommen bist, um mich abzuholen.",en:"Thank you for coming all the way to the station to pick me up."},{jp:"近[ちか]くにもあるのに、わざわざ遠[とお]い店[みせ]まで買[か]いに行[い]きました。",de:"Obwohl es auch in der Nähe einen gibt, bin ich extra zu einem weit entfernten Laden gefahren, um es zu kaufen.",en:"Although there is one nearby, I went all the way to a shop far away to buy it."}],matches:[],tags:["adverb","mühe"]},
  {id:"g-n3-tashika-ni",type:"grammar",source:"JLPT N3",level:"N3",title:"確かに – tatsächlich, in der Tat, zwar",jp:"たしかに",summary:"Bestätigt, dass etwas stimmt: „in der Tat, da haben Sie recht“. Sehr oft stimmt man damit erst einem Punkt zu, danach folgt nach が oder けど ein Einwand: „zwar …, aber …“. Nicht verwechseln: たしか (ohne に) heißt „wenn ich mich recht erinnere“.",structure:["たしかに + Satz","たしかに + A + が／けど、B"],examples:[{jp:"確[たし]かに、この店[みせ]の料理[りょうり]はおいしいですね。",de:"In der Tat, das Essen in diesem Lokal schmeckt gut.",en:"Indeed, the food at this restaurant is good."},{jp:"確[たし]かに値段[ねだん]は高[たか]いですが、品物[しなもの]はとてもいいです。",de:"Der Preis ist zwar hoch, aber die Ware ist sehr gut.",en:"It is true that the price is high, but the goods are very good."}],matches:[],tags:["adverb","zustimmung"]},
];
